"""Ingress-only display projection. Thin and HA retain all resource ownership.

No browser credentials, free-form tools, new conversation or LAN exception.
Mutations require an explicit server-installed room grant (not viewer identity).
"""

from __future__ import annotations

import asyncio
import copy
import hashlib
import ipaddress
import json
import os
import re
import secrets
import time
from pathlib import Path

from aiohttp import web

from . import podview_music, podview_robot, podview_weather
from .podview_music_selection import MusicSelection

BRIDGE: web.AppKey = web.AppKey("podview")
_PAIR_COOKIE = "podview_control"
_ALLOWED_PHASES = {"IDLE", "LISTENING", "THINKING", "AI_SPEAKING", "LOUNGE_WINDOW"}


def _trusted(remote: str | None) -> bool:
    try:
        address = ipaddress.ip_address(remote or "")
        return address.is_loopback or str(address) == "172.30.32.2"
    except ValueError:
        return False


def _error(kind: str, status: int = 409) -> web.Response:
    return web.json_response({"ok": False, "error": kind, "retryAllowed": False}, status=status)


def _music_public(
    kind: str,
    value: object,
    account: str | None = None,
    query: str | None = None,
) -> dict:
    """Display contract is closed even when owner/provider contracts retain extra fields."""
    unavailable = {"ok": False, "error": "music_unavailable", "retryAllowed": False}
    if kind in podview_music.SERVICES:
        if not isinstance(value, dict):
            return unavailable
        raw = value.get("data") if value.get("ok") is True else value
        return podview_music.project_owner(kind, raw, account, query=query)
    if kind in {"recent", "top", "liked"}:
        if not isinstance(value, dict) or value.get("ok") is not True:
            return unavailable
        data = value.get("data")
        tracks = data.get("tracks") if isinstance(data, dict) else None
        source_account = data.get("config_entry_id") if isinstance(data, dict) else None
        if (
            not isinstance(source_account, str)
            or not 1 <= len(source_account) <= 1024
            or (account is not None and source_account != account)
            or not isinstance(tracks, list)
            or len(tracks) > 50
        ):
            return unavailable
        projected_tracks = []
        for row in tracks:
            if (
                not isinstance(row, dict)
                or any(
                    not isinstance(row.get(key), str) or not row[key].strip()
                    for key in ("name", "artist", "uri")
                )
                or not row["uri"].startswith("spotify:track:")
            ):
                return unavailable
            item = {key: row[key] for key in ("name", "artist", "uri")}
            artwork = podview_music._artwork(row.get("artwork"))
            if artwork is not None:
                item["artwork"] = artwork
            projected_tracks.append(item)
        selection = value.get("selection")
        if not isinstance(selection, dict):
            return unavailable
        selected: dict = {
            "requested_limit": selection.get("requested_limit"),
            "source_sample_count": selection.get("source_sample_count"),
            "returned_count": selection.get("returned_count"),
            "more_in_sample": selection.get("more_in_sample"),
            "size_limited": selection.get("size_limited"),
            "coverage": "Source sample only; not a complete library or timestamped play history.",
        }
        if (
            any(
                type(selected[key]) is not int or not 0 <= selected[key] <= 50
                for key in ("requested_limit", "source_sample_count", "returned_count")
            )
            or any(type(selected[key]) is not bool for key in ("more_in_sample", "size_limited"))
            or selected["returned_count"] != len(projected_tracks)
        ):
            return unavailable
        result = {
            "ok": True,
            "data": {"config_entry_id": source_account, "tracks": projected_tracks},
            "selection": selected,
        }
        if not projected_tracks:
            result["empty"] = True
        return result
    if not isinstance(value, dict) or value.get("ok") is not True:
        return unavailable
    data = value.get("data")
    if not isinstance(data, dict):
        return unavailable
    if kind == "targets" and "targets" in data:
        rows = data["targets"]
        account = data.get("config_entry_id")
        if (
            not isinstance(account, str)
            or not 1 <= len(account) <= 1024
            or not isinstance(rows, list)
            or len(rows) > 256
        ):
            return unavailable
        targets = []
        for row in rows:
            if (
                not isinstance(row, dict)
                or row.get("kind") not in {"configured_alias", "spotify_device", "observed_output"}
                or any(
                    not isinstance(row.get(k), str) or not 1 <= len(row[k]) <= 1024
                    for k in ("target_id", "name")
                )
            ):
                return unavailable
            targets.append(
                {
                    "accountId": account,
                    "kind": row["kind"],
                    "targetId": row["target_id"],
                    "name": row["name"],
                    "readOnly": row["kind"] == "observed_output",
                    "restricted": row.get("restricted") is True,
                }
            )
        result = {
            "ok": True,
            "data": {"targets": targets},
            "coverage": "account_targets",
            "observedAt": time.time(),
        }
        return result if len(json.dumps(result).encode()) <= 65536 else unavailable
    fields: tuple[str, ...]
    if kind == "targets":
        rows = data.get("accounts")
        fields = ("config_entry_id", "title")
        key, maximum = "accounts", 64
    else:
        rows = data.get("tracks")
        fields = ("name", "artist", "uri")
        key, maximum = "tracks", 20
    if not isinstance(rows, list) or len(rows) > maximum:
        return unavailable
    if any(
        not isinstance(row, dict)
        or any(not isinstance(row.get(k), str) or not 1 <= len(row[k]) <= 1024 for k in fields)
        for row in rows
    ):
        return unavailable
    result = {
        "ok": True,
        "data": {key: [{k: row[k] for k in fields} for row in rows]},
        "coverage": "account_list" if kind == "targets" else "source_sample",
        "observedAt": time.time(),
    }
    return result if len(json.dumps(result).encode()) <= 65536 else unavailable


class PodViewBridge:
    def __init__(
        self,
        sessions: dict,
        tools=None,
        *,
        assets: Path | None = None,
        control_policy: str = "",
        pairing_room: str = "",
        pairing_sha256: str = "",
        pairing_store: Path | None = None,
    ) -> None:
        self.sessions, self.tools, self.assets = sessions, tools, assets
        self.boot_id = secrets.token_hex(16)
        from .podview_controls import TouchControls
        from .podview_music_control import MusicControlFacade

        self.controls = TouchControls(self, control_policy, MusicControlFacade(tools))
        self.music_selection = MusicSelection()
        self._touch_music_contexts: dict[tuple, tuple[float, dict]] = {}
        self._revisions: dict[str, tuple[str, int]] = {}
        self._grants: dict[str, tuple] = {}
        self._receipts: dict[str, tuple[str, dict]] = {}
        self._action_lock = asyncio.Lock()
        self._streams = 0
        self._music_cache: dict[tuple, tuple] = {}
        self._music_busy = False
        self._home_busy = False
        self._home_cache: dict[str, tuple] = {}
        self._home_revision = 0
        self._pairing_room = pairing_room
        self._pairing_hash = pairing_sha256 if re.fullmatch(r"[a-f0-9]{64}", pairing_sha256) else ""
        self._pairing_store = pairing_store
        self._pairing_deadline = time.monotonic() + 600
        self._pairing_attempts = 0
        attach = getattr(tools, "attach_podview_music_owner", None)
        if callable(attach):
            attach(self)

    def pair(self, room: object, code: object) -> str | None:
        """Consume administrator provisioned authority, never infer it from a viewer."""
        if (
            not self._pairing_hash
            or self._pairing_store is None
            or time.monotonic() >= self._pairing_deadline
            or self._pairing_attempts >= 5
        ):
            return None
        self._pairing_attempts += 1
        if (
            room != self._pairing_room
            or not isinstance(room, str)
            or not isinstance(code, str)
            or not re.fullmatch(r"[A-Za-z0-9_-]{32,128}", code)
            or not secrets.compare_digest(
                hashlib.sha256(code.encode()).hexdigest(), self._pairing_hash
            )
        ):
            return None
        try:
            token = self.grant_timer_control(room)
            store = self._pairing_store
            store.mkdir(parents=True, exist_ok=True, mode=0o700)
            if store.is_symlink():
                raise OSError("pairing store must be a directory")
            # O_EXCL fences concurrent use and persists one-use consumption across boots.
            fd = os.open(store / self._pairing_hash, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600)
            try:
                os.fsync(fd)
            finally:
                os.close(fd)
            directory = os.open(store, os.O_RDONLY | os.O_DIRECTORY)
            try:
                os.fsync(directory)
            finally:
                os.close(directory)
        except (OSError, ValueError):
            self.revoke(room)
            return None
        self._pairing_hash = ""
        return token

    def grant_timer_control(self, room: str) -> str:
        """Server owner only; HTTP pairing first proves administrator provisioned authority."""
        if room not in self.sessions:
            raise ValueError("unknown room")
        token = secrets.token_urlsafe(32)
        session = self.sessions[room]
        owner = getattr(getattr(session, "tools", None), "timers", None)
        if not owner or not owner.available(room):
            raise ValueError("timer owner unavailable")
        self._grants[room] = (
            token,
            session,
            owner,
            owner.snapshots[room]["epoch"],
            owner.bindings.get(room),
            time.monotonic() + 300,
        )
        return token

    def _grant_current(self, room: str, token: str) -> bool:
        grant = self._grants.get(room)
        if not grant:
            return False
        secret, session, owner, epoch, binding, deadline = grant
        return bool(
            secrets.compare_digest(secret, token)
            and time.monotonic() < deadline
            and self.sessions.get(room) is session
            and session is not None
            and session.tools.timers is owner
            and owner.available(room)
            and owner.snapshots.get(room, {}).get("epoch") == epoch
            and owner.bindings.get(room) == binding
        )

    def revoke(self, room: str) -> None:
        self._grants.pop(room, None)
        self.music_selection.sources.clear()
        self.music_selection.tasks.clear()

    def voice_music_available(self) -> bool:
        """Offer local voice tools only with a current controller and provider owner."""
        return any(
            self.controls.selection_allowed(room, grant[0]) for room, grant in self._grants.items()
        )

    def voice_music_room(self, context: object) -> str | None:
        if getattr(context, "approval_mode", None) != "live":
            return None
        matches = [
            room
            for room, session in self.sessions.items()
            if getattr(session, "_active", False)
            and getattr(context, "session_id", None) == getattr(session, "_history_session", None)
        ]
        return matches[0] if len(matches) == 1 else None

    def _voice_music_task(
        self, room: str, context: object, current, *, allow_consumed: bool = False
    ) -> tuple[dict, dict, tuple, str] | None:
        session = self.sessions.get(room)
        grant = self._grants.get(room)
        if (
            session is None
            or grant is None
            or not getattr(session, "_active", False)
            or getattr(context, "approval_mode", None) != "live"
            or getattr(context, "session_id", None) != getattr(session, "_history_session", None)
            or not current()
        ):
            return None
        token = grant[0]
        task = next(iter(self.music_selection.tasks.values()), None)
        if (
            task is None
            or task["context"]["roomId"] != room
            or (task["consumed"] and not allow_consumed)
        ):
            return None
        source = self.music_selection.sources.get(task["candidateSetId"])
        if (
            source is None
            or time.monotonic() >= task["deadline"]
            or not _selection_voice_source_current(self, source, room, token)
            or not _selection_rule_current(
                self, room, task["account"], task["target"], task["maxVolume"], grant
            )
        ):
            return None
        return task, source, grant, token

    def voice_music_options(self, room: str, context: object, current) -> dict:
        """The model sees only the same opaque options already offered to touch."""
        matched = self._voice_music_task(room, context, current)
        if matched is None:
            return {"ok": False, "error_kind": "stale_music_selection"}
        task = matched[0]
        return {
            "ok": True,
            "data": {
                "schema": "podview.music-selection.v1",
                "taskId": task["id"],
                "revision": task["context"]["revision"],
                "options": copy.deepcopy(task["publicOptions"]),
                "accountId": task["account"],
                "output": {
                    "kind": "spotify_device",
                    "targetId": task["target"],
                    "name": task["controls"]["target"]["name"],
                },
                "observedVolumePercent": task["volume"],
                "maxVolumePercent": task["maxVolume"],
            },
        }

    async def voice_music_select(
        self, room: str, context: object, args: dict, request_id: str, current
    ) -> dict:
        """Consume a reviewed voice choice through the same one-use broker as touch."""
        matched = self._voice_music_task(room, context, current)
        if matched is None:
            return {"ok": False, "error_kind": "stale_music_selection", "retry_allowed": False}
        task, source, grant, token = matched
        if args["taskId"] != task["id"]:
            return {"ok": False, "error_kind": "stale_music_selection", "retry_allowed": False}

        def selected_current() -> bool:
            return bool(
                current()
                and self.music_selection.tasks.get(task["id"]) is task
                and self.music_selection.sources.get(task["candidateSetId"]) is source
                and self._voice_music_task(room, context, lambda: True, allow_consumed=True)
                is not None
                and _selection_voice_source_current(self, source, room, token)
                and _selection_rule_current(
                    self, room, task["account"], task["target"], task["maxVolume"], grant
                )
            )

        async def fresh_controls():
            result = await self.controls.music.setup_track(
                task["account"], task["target"], selected_current
            )
            return result.get("data", {}) if result.get("ok") is True else {}

        result = await self.music_selection.execute(
            task_id=task["id"],
            revision=args["revision"],
            option_id=args["optionId"],
            request_id=request_id,
            confirmed_volume=args["confirmedVolumePercent"],
            context=source["context"],
            owner_binding=source["binding"],
            authority=task["authority"],
            current=selected_current,
            fresh_controls=fresh_controls,
            send_once=self.controls.music.execute_track,
        )
        return {"ok": result["ok"], "data": result}

    @staticmethod
    def _timer_history(state: dict) -> dict:
        result: dict = {"status": "unavailable", "scope": "core_lifetime", "items": []}
        rows = state.get("recent")
        if not isinstance(rows, list) or len(rows) > 12:
            return result
        seen = set()
        previous = float("inf")
        for row in rows:
            if (
                not isinstance(row, dict)
                or set(row) != {"id", "name", "seconds", "accepted_at"}
                or not isinstance(row["id"], str)
                or not 1 <= len(row["id"]) <= 200
                or row["id"] in seen
                or not isinstance(row["name"], str)
                or len(row["name"]) > 120
                or type(row["seconds"]) is not int
                or not 1 <= row["seconds"] <= 86400
                or type(row["accepted_at"]) not in (int, float)
                or not 0 < row["accepted_at"] <= min(previous, time.time() + 5)
            ):
                return {**result, "items": []}
            seen.add(row["id"])
            previous = row["accepted_at"]
            result["items"].append(
                {
                    "id": row["id"],
                    "name": row["name"],
                    "seconds": row["seconds"],
                    "acceptedAt": row["accepted_at"],
                }
            )
        result["status"] = "observed"
        return result

    def snapshot(self, room: str, token: str = "") -> dict:
        session = self.sessions[room]
        active = bool(getattr(session, "_active", False))
        state = getattr(getattr(session, "sm", None), "state", None)
        phase = getattr(state, "name", str(state))
        if phase not in _ALLOWED_PHASES:
            phase = "UNKNOWN"
        closing = bool(
            getattr(session, "_closing", False) or getattr(session, "_transport_closing", False)
        )
        voice = {
            "phase": "CLOSING" if closing else phase,
            "sessionId": getattr(session, "_history_session", None) if active else None,
            "turnId": session._external_turn_id() if active else None,
            "active": active,
        }
        timer_owner = getattr(getattr(session, "tools", None), "timers", None)
        fresh = bool(timer_owner and timer_owner.available(room))
        timer_state = timer_owner.snapshots.get(room, {}) if fresh and timer_owner else {}
        if fresh and any(
            row.get("state") not in {"active", "paused"} for row in timer_state.get("timers", [])
        ):
            fresh = False
            timer_state = {}
        items = [
            {
                "id": row["id"],
                "name": row["name"],
                "secondsLeft": row["seconds_left"],
                "status": "paused"
                if status == "running" and row.get("state") == "paused"
                else status,
                "alertState": row.get("alert_state"),
                "physicalStopped": row.get("physical_stopped"),
                "physicalDrained": row.get("physical_drained"),
            }
            for group, status in (("timers", "running"), ("finished", "finished"))
            for row in timer_state.get(group, [])
        ]
        music_reads: list[str] = getattr(self.tools, "podview_music_reads", lambda: [])()
        receipt_owner = getattr(self.tools, "podview_receipts", None)
        answers = (
            receipt_owner.snapshot(room, self.sessions[room]) if receipt_owner is not None else None
        )
        latest_answer = answers["items"][0] if answers and answers["items"] else {}
        result: dict = {
            "answers": {
                "revision": answers["revision"] if answers else 0,
                **(
                    {
                        key: latest_answer.get(key)
                        for key in ("sessionEpoch", "providerGeneration", "answerRevision")
                    }
                    if latest_answer.get("schema") == "podview.research.v1"
                    else {}
                ),
                **{
                    key: latest_answer.get(key)
                    for key in ("sessionId", "turnId", "taskId", "inputRevision")
                },
            },
            "schema": "podview.snapshot.v1",
            "bootId": self.boot_id,
            "roomId": room,
            "voice": voice,
            "timers": {
                "status": "observed" if fresh else "unavailable",
                "items": items,
                "epoch": timer_state.get("epoch"),
                "owner": "home_assistant_intent",
            },
            "timerHistory": self._timer_history(timer_state)
            if fresh
            else {"status": "unavailable", "scope": "core_lifetime", "items": []},
            "capabilities": {
                "timerRead": fresh,
                "homeRead": [
                    kind
                    for kind, method in (
                        ("vacuum", "podview_home_available"),
                        ("weather", "podview_weather_available"),
                    )
                    if getattr(self.tools, method, lambda: False)()
                ],
                "timerActions": [],
                "musicRead": music_reads,
                "musicActions": [],
                "musicSelection": False,
                "answerRead": receipt_owner is not None,
                "controlSetup": [],
                "visualEnrichment": bool(getattr(receipt_owner, "selection_enabled", False)),
                "researchVisual": bool(getattr(receipt_owner, "research_admitted", False)),
            },
        }
        # No grant is disclosed to viewers. A paired controller supplies its own token.
        encoded = json.dumps(result, sort_keys=True, allow_nan=False)
        digest = hashlib.sha256(encoded.encode()).hexdigest()
        old, revision = self._revisions.get(room, ("", 0))
        revision += digest != old
        self._revisions[room] = digest, revision
        # Authorization is per connection, not part of the shared resource revision.
        if fresh and self._grant_current(room, token):
            result["capabilities"]["timerActions"] = ["timer.start", "timer.cancel"]
        result["capabilities"]["controlSetup"] = self.controls.domains(room, token)
        result["capabilities"]["musicSelection"] = self.controls.selection_allowed(room, token)
        return {**result, "revision": revision, "observedAt": time.time()}

    async def action(self, body: dict, token: str) -> dict:
        required = {"bootId", "roomId", "taskId", "revision", "requestId", "action", "args"}
        if set(body) != required or not isinstance(body.get("roomId"), str):
            return {"ok": False, "error": "invalid_action", "retryAllowed": False}
        room = body["roomId"]
        grant = self._grants.get(room)
        if not self._grant_current(room, token):
            return {"ok": False, "error": "control_not_paired", "retryAllowed": False}
        request_id = body["requestId"]
        if not isinstance(request_id, str) or not 1 <= len(request_id) <= 120:
            return {"ok": False, "error": "invalid_request", "retryAllowed": False}
        fingerprint = hashlib.sha256(json.dumps(body, sort_keys=True).encode()).hexdigest()
        key = room + ":" + request_id
        async with self._action_lock:
            if key in self._receipts:
                before, receipt = self._receipts[key]
                return (
                    receipt
                    if before == fingerprint
                    else {"ok": False, "error": "request_reused", "retryAllowed": False}
                )
            if not self._grant_current(room, token):
                return {"ok": False, "error": "control_not_paired", "retryAllowed": False}
            snap = self.snapshot(room)
            if snap["timers"]["status"] != "observed":
                return {"ok": False, "error": "timer_unavailable", "retryAllowed": False}
            if (
                body["bootId"] != self.boot_id
                or type(body["revision"]) is not int
                or body["revision"] != snap["revision"]
                or body["taskId"] != f"timers:{snap['timers']['epoch']}"
            ):
                return {"ok": False, "error": "stale_action", "retryAllowed": False}
            owner = getattr(getattr(self.sessions[room], "tools", None), "timers", None)
            args, action = body["args"], body["action"]
            if not isinstance(args, dict) or not owner or not owner.available(room):
                return {"ok": False, "error": "timer_unavailable", "retryAllowed": False}
            valid = (
                action == "timer.start"
                and set(args) <= {"seconds", "name"}
                and type(args.get("seconds")) is int
                and 1 <= args["seconds"] <= 86400
                and isinstance(args.get("name", ""), str)
                and len(args.get("name", "")) <= 120
            )
            valid |= (
                action == "timer.cancel"
                and set(args) == {"timer_id"}
                and isinstance(args["timer_id"], str)
                and args["timer_id"] in {r["id"] for r in snap["timers"]["items"]}
            )
            if not valid:
                return {"ok": False, "error": "unsupported_action", "retryAllowed": False}
            if len(self._receipts) >= 1024:
                return {"ok": False, "error": "request_capacity", "retryAllowed": False}
            receipt = {
                "ok": False,
                "requestId": request_id,
                "outcome": "unknown",
                "retryAllowed": False,
            }
            self._receipts[key] = fingerprint, receipt  # fence before the first await
            epoch = snap["timers"]["epoch"]

            def current():
                return (
                    self._grants.get(room) == grant
                    and self._grant_current(room, token)
                    and owner.available(room)
                    and owner.snapshots[room].get("epoch") == epoch
                )

            try:
                result = await asyncio.wait_for(
                    owner.dispatch(
                        "podvoice_start_timer"
                        if action == "timer.start"
                        else "podvoice_cancel_timer",
                        args,
                        room,
                        "podview:" + self.boot_id,
                        request_id,
                        execution_guard=current,
                    ),
                    timeout=8,
                )
                receipt = {
                    "ok": result.get("ok") is True,
                    "requestId": request_id,
                    "outcome": "accepted" if result.get("ok") is True else "unknown",
                    "retryAllowed": False,
                    "physicalResultVerified": False,
                }
                self._receipts[key] = fingerprint, receipt
            except (TimeoutError, Exception):
                pass  # no diagnostic/secret exception detail crosses the display boundary
            return receipt


async def _control(request: web.Request) -> web.Response:
    denied = await _guard(request)
    if denied is not None:
        return denied
    if request.content_length is None or request.content_length > 4096:
        return _error("bounded_body_required", 413)
    try:
        body = await request.json()
        if not isinstance(body, dict):
            raise ValueError
    except (ValueError, json.JSONDecodeError):
        return _error("invalid_control", 400)
    owner = request.app[BRIDGE].controls
    handler = owner.setup if request.path.endswith("/setup") else owner.action
    result = await handler(body, request.cookies.get(_PAIR_COOKIE, ""))
    return web.json_response(result, headers={"Cache-Control": "no-store"})


async def _guard(request: web.Request) -> web.Response | None:
    if not _trusted(request.remote):
        return _error("ingress_required", 403)
    if request.headers.get("Sec-Fetch-Site") not in (None, "same-origin", "none"):
        return _error("cross_origin_denied", 403)
    if request.method == "POST" and (
        request.headers.get("X-PodView-Request") != "1"
        or request.content_type != "application/json"
    ):
        return _error("request_header_required", 403)
    return None


def _room(request: web.Request, bridge: PodViewBridge) -> str | None:
    room = request.query.get("room")
    if room is None and len(bridge.sessions) == 1:
        room = next(iter(bridge.sessions))
    return room if room in bridge.sessions else None


async def _snapshot(request: web.Request) -> web.Response:
    denied = await _guard(request)
    if denied is not None:
        return denied
    bridge = request.app[BRIDGE]
    room = _room(request, bridge)
    if room is None:
        return web.json_response(
            {"ok": False, "error": "room_required", "rooms": list(bridge.sessions)}, status=409
        )
    return web.json_response(
        bridge.snapshot(room, request.cookies.get(_PAIR_COOKIE, "")),
        headers={"Cache-Control": "no-store"},
    )


async def _events(request: web.Request) -> web.StreamResponse:
    denied = await _guard(request)
    if denied is not None:
        return denied
    bridge = request.app[BRIDGE]
    room = _room(request, bridge)
    if room is None:
        return _error("room_required")
    if bridge._streams >= 8:
        return _error("stream_capacity", 429)
    bridge._streams += 1
    response = web.StreamResponse(
        headers={
            "Content-Type": "text/event-stream",
            "Cache-Control": "no-store",
            "X-Accel-Buffering": "no",
        }
    )
    try:
        await response.prepare(request)
        # Every tick is a fresh full projection; dropped events cannot corrupt a delta.
        # This reads caches only: it never polls HA or holds an audio-owner lock.
        while True:
            snap = bridge.snapshot(room, request.cookies.get(_PAIR_COOKIE, ""))
            payload = f"event: snapshot\nid: {bridge.boot_id}:{snap['revision']}\ndata: {json.dumps(snap)}\n\n"
            await asyncio.wait_for(response.write(payload.encode()), timeout=5)
            await asyncio.sleep(1)
    except (ConnectionResetError, TimeoutError, asyncio.CancelledError):
        pass
    finally:
        bridge._streams -= 1
    return response


async def _pair(request: web.Request) -> web.Response:
    denied = await _guard(request)
    if denied is not None:
        return denied
    if request.content_length is None or request.content_length > 1024:
        return _error("bounded_body_required", 413)
    try:
        body = await request.json()
        if not isinstance(body, dict) or set(body) != {"roomId", "code"}:
            raise ValueError
    except (ValueError, json.JSONDecodeError):
        return _error("invalid_pairing", 400)
    # Ingress supplies this path; never accept arbitrary cookie domains or traversal.
    prefix = request.headers.get("X-Ingress-Path", "")
    if prefix and not re.fullmatch(r"/api/hassio_ingress/[A-Za-z0-9_-]+", prefix):
        return _error("invalid_ingress_path", 403)
    token = request.app[BRIDGE].pair(body["roomId"], body["code"])
    if token is None:
        return _error("pairing_denied", 403)
    response = web.json_response(
        {"ok": True, "paired": True, "expiresIn": 300}, headers={"Cache-Control": "no-store"}
    )
    response.set_cookie(
        _PAIR_COOKIE,
        token,
        max_age=300,
        httponly=True,
        samesite="Strict",
        secure=request.secure or request.headers.get("X-Forwarded-Proto") == "https",
        path=prefix + "/view/",
    )
    return response


async def _actions(request: web.Request) -> web.Response:
    denied = await _guard(request)
    if denied is not None:
        return denied
    if request.content_length is None or request.content_length > 4096:
        return _error("bounded_body_required", 413)
    try:
        body = await request.json()
        if not isinstance(body, dict):
            raise ValueError
    except (ValueError, json.JSONDecodeError):
        return _error("invalid_json", 400)
    result = await request.app[BRIDGE].action(body, request.cookies.get(_PAIR_COOKIE, ""))
    return web.json_response(
        result, status=200 if result.get("ok") else 409, headers={"Cache-Control": "no-store"}
    )


def _music_binding(bridge: PodViewBridge, room: str) -> tuple:
    tools, session = bridge.tools, bridge.sessions.get(room)
    session_tools = getattr(session, "tools", None)
    return (
        tools,
        id(tools),
        tools.podview_music_binding(),
        session,
        id(session),
        session_tools,
        id(session_tools),
        getattr(session, "_history_session", None),
        getattr(session, "_epoch", None),
    )


def _music_search_context(
    bridge: PodViewBridge,
    room: str,
    account: str,
    query: str,
    token: str = "",
    *,
    mint_touch: bool = False,
) -> dict:
    """Read the current owner context; mint touch ownership only at an admitted read."""
    snapshot = bridge.snapshot(room)
    voice = snapshot.get("voice")
    answers = snapshot.get("answers")
    if not isinstance(voice, dict):
        voice = {}
    if not isinstance(answers, dict):
        answers = {}
    voice_task = (
        isinstance(voice.get("sessionId"), str)
        and isinstance(voice.get("turnId"), str)
        and answers.get("sessionId") == voice.get("sessionId")
        and answers.get("turnId") == voice.get("turnId")
        and isinstance(answers.get("taskId"), str)
        and type(answers.get("inputRevision")) is int
    )
    if not voice_task and bridge._grant_current(room, token):
        key = (room, account, query, hashlib.sha256(token.encode()).hexdigest())
        saved = bridge._touch_music_contexts.get(key)
        if (saved is None or saved[0] <= time.monotonic()) and mint_touch:
            touch = {
                "sessionId": "touch:" + secrets.token_hex(16),
                "turnId": "touch:" + secrets.token_hex(16),
                "taskId": "music:" + secrets.token_hex(16),
                "inputRevision": 1,
                "revision": 1,
            }
            bridge._touch_music_contexts = {key: (time.monotonic() + 60, touch)}
        elif saved is not None and saved[0] > time.monotonic():
            touch = saved[1]
        else:
            touch = None
    else:
        touch = None
    context = {
        "schema": "podview.music-search-context.v1",
        "bootId": snapshot.get("bootId"),
        "roomId": room,
        "revision": touch["revision"] if touch else answers.get("revision"),
        "revisionScope": "music_selection" if touch else "answer_task",
        "sessionId": touch["sessionId"] if touch else voice.get("sessionId"),
        "turnId": touch["turnId"] if touch else voice.get("turnId"),
        "taskId": touch["taskId"] if touch else answers.get("taskId"),
        "inputRevision": touch["inputRevision"] if touch else answers.get("inputRevision"),
        "configEntryId": account,
        "source": "spotify_web_api",
        "query": query,
    }
    return context


def _selection_source_current(bridge: PodViewBridge, source: dict, room: str, token: str) -> bool:
    context = source["context"]
    return bool(
        bridge._grant_current(room, token)
        and bridge.controls.selection_allowed(room, token)
        and context.get("roomId") == room
        and _music_binding(bridge, room) == source["binding"]
        and _music_search_context(bridge, room, context["configEntryId"], context["query"], token)
        == context
    )


def _selection_voice_source_current(
    bridge: PodViewBridge, source: dict, room: str, token: str
) -> bool:
    """A later trusted approval turn may retain the exact original answer task."""
    context = source["context"]
    if context.get("revisionScope") != "answer_task":
        return _selection_source_current(bridge, source, room, token)
    snapshot = bridge.snapshot(room, token)
    answer = snapshot.get("answers", {})
    voice = snapshot.get("voice", {})
    return bool(
        bridge._grant_current(room, token)
        and bridge.controls.selection_allowed(room, token)
        and context.get("roomId") == room
        and _music_binding(bridge, room) == source["binding"]
        and voice.get("sessionId") == context.get("sessionId")
        and all(
            answer.get(key) == context.get(key)
            for key in ("sessionId", "turnId", "taskId", "inputRevision", "revision")
        )
    )


def _selection_rule_current(
    bridge: PodViewBridge, room: str, account: str, target_id: str, max_volume: int, grant: tuple
) -> bool:
    """An old offer cannot outlive its exact room grant or action rule."""
    rules = bridge.controls.policy.get("music")
    return bool(
        bridge._grants.get(room) is grant
        and bridge.controls.policy.get("roomId") == room
        and isinstance(rules, list)
        and any(
            isinstance(row, dict)
            and row.get("accountId") == account
            and row.get("targetId") == target_id
            and row.get("maxVolume") == max_volume
            and isinstance(row.get("actions"), list)
            and "play_track" in row["actions"]
            for row in rules
        )
    )


def _music_search_candidate_set(context: dict, data: object) -> dict | None:
    if not isinstance(data, dict):
        return None
    source = {"context": context, "data": data}
    candidate_set_id = hashlib.sha256(
        json.dumps(source, sort_keys=True, separators=(",", ":"), allow_nan=False).encode()
    ).hexdigest()
    return {**context, "candidateSetId": candidate_set_id}


async def _answers(request: web.Request) -> web.Response:
    denied = await _guard(request)
    if denied is not None:
        return denied
    bridge = request.app[BRIDGE]
    room = _room(request, bridge)
    if room is None or set(request.query) - {"room"}:
        return _error("unknown_room", 404)
    sink = getattr(bridge.tools, "podview_receipts", None)
    if sink is None:
        return _error("answers_unavailable", 404)
    receipt_id = request.match_info.get("receipt_id")
    if receipt_id is not None:
        if re.fullmatch(r"[a-f0-9]{32}", receipt_id) is None:
            return _error("unknown_source", 404)
        result = sink.source(room, receipt_id, bridge.sessions[room])
        if result is None:
            return _error("unknown_source", 404)
    else:
        result = sink.snapshot(room, bridge.sessions[room])
    return web.json_response(result, headers={"Cache-Control": "no-store"})


async def _music(request: web.Request) -> web.Response:
    denied = await _guard(request)
    if denied is not None:
        return denied
    bridge = request.app[BRIDGE]
    room = _room(request, bridge)
    if room is None:
        return _error("room_required")
    tools = bridge.tools
    if not all(
        hasattr(tools, method)
        for method in ("podview_read", "podview_music_reads", "podview_music_binding")
    ):
        bridge._music_cache.clear()
        return _error("music_unavailable", 503)
    kind = request.query.get("kind", "targets")
    if kind not in {"targets", "recent", "top", "liked", "playback", "queue", "search"}:
        return _error("unsupported_read", 400)
    account = request.query.get("account")
    query = None
    if kind == "search":
        try:
            values = request.query.getall("query", [])
            if len(values) != 1:
                raise ValueError("missing or repeated query")
            query = podview_music.normalize_search_query(values[0])
        except ValueError:
            return _error("invalid_query", 400)
    elif "query" in request.query:
        return _error("invalid_query", 400)
    library_kinds = {"recent", "top", "liked"}
    if (
        account is not None
        and (
            kind not in {"targets", "playback", "queue", "search", *library_kinds}
            or not 1 <= len(account) <= 1024
        )
    ) or (kind in podview_music.SERVICES and account is None):
        return _error("invalid_account", 400)
    if kind not in tools.podview_music_reads():
        bridge._music_cache.clear()
        return _error("music_unavailable", 503)
    binding = _music_binding(bridge, room)
    token = request.cookies.get(_PAIR_COOKIE, "")
    selection_requested = bool(
        kind == "search"
        and bridge._grant_current(room, token)
        and bridge.controls.selection_allowed(room, token)
    )
    search_context = (
        _music_search_context(bridge, room, account, query, token)
        if kind == "search" and account is not None and query is not None
        else None
    )
    cache_key = (
        room,
        kind,
        account,
        query,
        json.dumps(search_context, sort_keys=True, separators=(",", ":"), allow_nan=False)
        if search_context is not None
        else None,
    )
    # Old owner values may neither be returned nor consume the bounded cache.
    bridge._music_cache = {
        key: value
        for key, value in bridge._music_cache.items()
        if time.monotonic() - value[0] < value[3]
        and key[0] in bridge.sessions
        and value[1] == _music_binding(bridge, key[0])
        and key[1] in tools.podview_music_reads()
    }
    cached = bridge._music_cache.get(cache_key) if not selection_requested else None
    if cached:
        result = (
            _music_public(kind, cached[2], account, query)
            if kind in podview_music.SERVICES
            else cached[2]
        )
        if kind == "search" and result.get("ok") and search_context is not None:
            candidate_set = _music_search_candidate_set(search_context, result.get("data"))
            if candidate_set is not None:
                result["candidateSet"] = candidate_set
        return web.json_response(result, headers={"Cache-Control": "no-store"})
    if kind != "playback" and len(bridge._music_cache) >= 16:
        return _error("music_capacity", 429)
    if bridge._music_busy:
        return _error("music_busy", 429)
    bridge._music_busy = True
    before_epoch = None
    try:
        if kind == "search" and selection_requested:
            assert account is not None and query is not None
            search_context = _music_search_context(
                bridge, room, account, query, token, mint_touch=True
            )
        if kind == "search":
            if selection_requested and "playback" in tools.podview_music_reads():
                before = await asyncio.wait_for(tools.podview_read("playback", account), timeout=10)
                if before.get("ok") is True:
                    before_epoch = before.get("data", {}).get("owner_epoch")
            raw = await asyncio.wait_for(tools.podview_read(kind, account, query), timeout=10)
        else:
            raw = await asyncio.wait_for(tools.podview_read(kind, account), timeout=10)
        result = _music_public(kind, raw, account, query)
    except Exception:
        result = {"ok": False, "error": "music_unavailable", "retryAllowed": False}
    finally:
        bridge._music_busy = False
    if (
        bridge.tools is not tools
        or room not in bridge.sessions
        or binding != _music_binding(bridge, room)
        or kind not in tools.podview_music_reads()
    ):
        return _error("music_unavailable", 503)
    if kind == "search":
        assert account is not None and query is not None
        current_context = _music_search_context(
            bridge, room, account, query, request.cookies.get(_PAIR_COOKIE, "")
        )
        if current_context != search_context:
            return _error("music_unavailable", 503)
        if result.get("ok") and search_context is not None:
            candidate_set = _music_search_candidate_set(search_context, result.get("data"))
            if candidate_set is not None:
                if not selection_requested:
                    result["candidateSet"] = candidate_set
                else:
                    after_epoch = None
                    try:
                        after = await asyncio.wait_for(
                            tools.podview_read("playback", account), timeout=10
                        )
                        if after.get("ok") is True:
                            after_epoch = after.get("data", {}).get("owner_epoch")
                    except Exception:
                        pass
                    if (
                        before_epoch is not None
                        and after_epoch == before_epoch
                        and binding == _music_binding(bridge, room)
                        and current_context
                        == _music_search_context(bridge, room, account, query, token)
                    ):
                        identifier = bridge.music_selection.register(
                            search_context, result["data"], binding, before_epoch, after_epoch
                        )
                        if identifier is not None:
                            result["candidateSet"] = {**candidate_set, "candidateSetId": identifier}
    # Playback must consult its owner again; it never gets a fresh bridge timestamp.
    if kind != "playback" and not selection_requested:
        bridge._music_cache[cache_key] = (
            time.monotonic(),
            binding,
            result,
            2 if kind == "queue" else 15,
        )
    return web.json_response(result, headers={"Cache-Control": "no-store"})


async def _music_selection(request: web.Request) -> web.Response:
    """One short-lived server option set; the browser never supplies a Spotify URI."""
    denied = await _guard(request)
    if denied is not None:
        return denied
    if request.content_length is None or request.content_length > 4096:
        return _error("bounded_body_required", 413)
    try:
        body = await request.json()
        if not isinstance(body, dict):
            raise ValueError
    except (ValueError, json.JSONDecodeError):
        return _error("invalid_music_selection", 400)
    bridge = request.app[BRIDGE]
    token = request.cookies.get(_PAIR_COOKIE, "")
    room = body.get("roomId")
    if (
        not isinstance(room, str)
        or room not in bridge.sessions
        or body.get("bootId") != bridge.boot_id
        or not bridge._grant_current(room, token)
        or not bridge.controls.selection_allowed(room, token)
    ):
        return _error("music_selection_not_paired", 403)

    def source_current(source: dict) -> bool:
        return _selection_source_current(bridge, source, room, token)

    def exact_rule_current(account: str, target_id: str, max_volume: int, grant: tuple) -> bool:
        return _selection_rule_current(bridge, room, account, target_id, max_volume, grant)

    if request.path.endswith("/setup"):
        if set(body) != {"bootId", "roomId", "candidateSetId", "target"} or not isinstance(
            body["candidateSetId"], str
        ):
            return _error("invalid_music_selection", 400)
        source = bridge.music_selection.sources.get(body["candidateSetId"])
        target = body["target"]
        if (
            source is None
            or not isinstance(target, dict)
            or set(target) != {"accountId", "kind", "targetId"}
            or target["kind"] != "spotify_device"
            or target["accountId"] != source["context"]["configEntryId"]
            or not source_current(source)
        ):
            return _error("stale_music_selection")
        rule = next(
            (
                row
                for row in bridge.controls.policy["music"]
                if row["accountId"] == target["accountId"]
                and row["targetId"] == target["targetId"]
                and "play_track" in row["actions"]
            ),
            None,
        )
        if rule is None:
            return _error("target_not_granted", 403)
        grant = bridge._grants.get(room)
        if grant is None:
            return _error("music_selection_not_paired", 403)

        def selected_current() -> bool:
            return bool(
                source_current(source)
                and exact_rule_current(
                    target["accountId"], target["targetId"], rule["maxVolume"], grant
                )
            )

        facade = bridge.controls.music
        controls = await facade.setup_track(
            target["accountId"], target["targetId"], selected_current
        )
        if controls.get("ok") is not True or not selected_current():
            return _error("music_selection_unavailable")
        context = source["context"]
        session = bridge.sessions[room]
        authority = (session, getattr(session, "_epoch", None), context["taskId"], grant)
        offer = bridge.music_selection.offer(
            identifier=body["candidateSetId"],
            context=context,
            owner_binding=source["binding"],
            account=target["accountId"],
            target=target["targetId"],
            observed_controls=controls["data"],
            approved_max_volume=rule["maxVolume"],
            authority=authority,
            current=selected_current,
        )
        return web.json_response(
            offer
            if offer is not None
            else {"ok": False, "error": "stale_music_selection", "retryAllowed": False},
            headers={"Cache-Control": "no-store"},
        )

    if set(body) != {
        "bootId",
        "roomId",
        "taskId",
        "revision",
        "requestId",
        "optionId",
        "confirmedVolumePercent",
    } or not isinstance(body["taskId"], str):
        return _error("invalid_music_selection", 400)
    task = bridge.music_selection.tasks.get(body["taskId"])
    if task is None or task["context"]["roomId"] != room:
        return _error("stale_music_selection")
    source = bridge.music_selection.sources.get(task["candidateSetId"])
    if source is None or not source_current(source):
        return _error("stale_music_selection")
    grant = task["authority"][-1]

    def action_current() -> bool:
        return bool(
            source_current(source)
            and exact_rule_current(task["account"], task["target"], task["maxVolume"], grant)
        )

    facade = bridge.controls.music

    async def fresh_controls():
        result = await facade.setup_track(task["account"], task["target"], action_current)
        return result.get("data", {}) if result.get("ok") is True else {}

    result = await bridge.music_selection.execute(
        task_id=body["taskId"],
        revision=body["revision"],
        option_id=body["optionId"],
        request_id=body["requestId"],
        confirmed_volume=body["confirmedVolumePercent"],
        context=source["context"],
        owner_binding=source["binding"],
        authority=task["authority"],
        current=action_current,
        fresh_controls=fresh_controls,
        send_once=facade.execute_track,
    )
    return web.json_response(result, headers={"Cache-Control": "no-store"})


def _home_history(value: object, entity_id: str) -> dict:
    """Display only owner receipts; IDs never carry action authority."""
    unavailable = {"status": "unavailable", "items": []}
    if not isinstance(value, dict) or value.get("status") != "observed":
        return unavailable
    if value.get("source") != "device_control_start_journal" or value.get("durable") is not True:
        return unavailable
    rows = value.get("items")
    if not isinstance(rows, list) or len(rows) > 3:
        return unavailable
    from .cleaning_journal import _record

    items: list[dict] = []
    for raw in rows:
        if not isinstance(raw, dict):
            return unavailable
        row = {
            key: raw.get(key) for key in ("id", "recorded_at", "accepted_at", "outcome", "recipe")
        }
        recipe = row["recipe"]
        if not _record(row) or not isinstance(recipe, dict):
            return unavailable
        if recipe["vacuum_entity_id"] != entity_id:
            return unavailable
        items.append(
            {
                "id": row["id"],
                "recordedAt": row["recorded_at"],
                "acceptedAt": row["accepted_at"],
                "outcome": row["outcome"],
                "recipe": {
                    "areaIds": recipe["area_ids"],
                    "mapName": recipe["map_name"],
                    "repeat": recipe["repeat"],
                    "verifiedSettings": [
                        {"entityId": v["entity_id"], "value": v["value"]}
                        for v in recipe["verified_settings"]
                    ],
                },
                "physicalResultVerified": False,
                "actions": [],
            }
        )
    return {"status": "observed", "source": "device_control_start_journal", "items": items}


def _home_vacuum(value: object) -> dict:
    unavailable = {"status": "unavailable", "items": []}
    if not isinstance(value, dict) or value.get("status") != "observed":
        return unavailable
    items = value.get("items")
    if not isinstance(items, list) or len(items) > 12:
        return unavailable
    result, seen = [], set()
    for row in items:
        if (
            not isinstance(row, dict)
            or not isinstance(row.get("entityId"), str)
            or not re.fullmatch(r"vacuum\.[a-z0-9_]+", row["entityId"])
            or row["entityId"] in seen
            or not isinstance(row.get("state"), str)
            or row.get("state")
            not in {
                "cleaning",
                "paused",
                "returning",
                "docked",
                "idle",
                "error",
                "unknown",
                "unavailable",
            }
            or row.get("source") != "home_assistant_state"
            or not isinstance(row.get("name"), str)
            or type(row.get("observedAt")) not in {int, float}
            or not 0 <= row["observedAt"] <= time.time() + 1
        ):
            return unavailable
        seen.add(row["entityId"])
        battery = row.get("battery")
        result.append(
            {
                "entityId": row["entityId"],
                "name": row["name"][:120],
                "state": row["state"],
                "battery": battery
                if isinstance(battery, (int, float))
                and not isinstance(battery, bool)
                and 0 <= battery <= 100
                else None,
                "observedAt": row["observedAt"],
                "source": "home_assistant_state",
                "settings": {"status": "unavailable", "items": []},
                "history": _home_history(row.get("history"), row["entityId"]),
                "telemetry": podview_robot.project(row.get("telemetry"), row["entityId"]),
                "actions": [],
            }
        )
    return {"status": "observed", "items": result}


async def _home(request: web.Request) -> web.Response:
    denied = await _guard(request)
    if denied is not None:
        return denied
    bridge = request.app[BRIDGE]
    room = _room(request, bridge)
    if room is None:
        return _error("room_required")
    tools = bridge.tools
    if not tools or not all(
        hasattr(tools, name)
        for name in ("podview_home_read", "podview_home_binding", "podview_home_available")
    ):
        return _error("home_unavailable", 503)

    def binding_now():
        return (
            tools,
            (tools.podview_home_binding(), tools.podview_home_available()),
            (
                getattr(tools, "podview_weather_binding", lambda: None)(),
                getattr(tools, "podview_weather_available", lambda: False)(),
            ),
            bridge.sessions.get(room),
        )

    binding = binding_now()
    cached = bridge._home_cache.get(room)
    if (
        cached
        and cached[1] == binding
        and time.monotonic() - cached[0] < 5
        and podview_weather.observation_is_current(cached[2].get("weather"))
    ):
        return web.json_response(cached[2], headers={"Cache-Control": "no-store"})
    if bridge._home_busy:
        return _error("home_busy", 429)
    bridge._home_busy = True

    async def read_domain(method, unavailable):
        try:
            read = getattr(tools, method, None)
            return await asyncio.wait_for(read(), timeout=8) if read else unavailable
        except Exception:
            return unavailable

    try:
        raw, weather = await asyncio.gather(
            read_domain("podview_home_read", {"status": "unavailable", "items": []}),
            read_domain("podview_weather_read", {"status": "unavailable", "data": None}),
        )
        latest = binding_now()
        same_owner = tools is bridge.tools and binding[3] is latest[3]
        vacuum = (
            _home_vacuum(raw)
            if same_owner and binding[1] == latest[1] and tools.podview_home_available()
            else {"status": "unavailable", "items": []}
        )
        if not (
            same_owner
            and binding[2] == latest[2]
            and getattr(tools, "podview_weather_available", lambda: False)()
        ):
            weather = {"status": "unavailable", "data": None}
    finally:
        bridge._home_busy = False
    bridge._home_revision += 1
    result = {
        "schema": "podview.home.v1",
        "bootId": bridge.boot_id,
        "roomId": room,
        "revision": bridge._home_revision,
        "observedAt": time.time(),
        "vacuum": vacuum,
        "weather": weather,
    }
    bridge._home_cache[room] = time.monotonic(), binding, result
    return web.json_response(result, headers={"Cache-Control": "no-store"})


async def _assets(request: web.Request) -> web.StreamResponse:
    denied = await _guard(request)
    if denied is not None:
        return denied
    root = request.app[BRIDGE].assets
    name = request.match_info.get("asset", "") or "index.html"
    if not root or not root.is_dir():
        return _error("view_assets_not_packaged", 503)
    target = (root / name).resolve()
    if (
        not target.is_relative_to(root.resolve())
        or not target.is_file()
        or target.suffix
        not in {".html", ".js", ".css", ".svg", ".png", ".jpg", ".jpeg", ".webp", ".woff2"}
    ):
        raise web.HTTPNotFound()
    return web.FileResponse(
        target,
        headers={
            "Cache-Control": "no-cache",
            "X-Content-Type-Options": "nosniff",
            "Referrer-Policy": "same-origin",
        },
    )


def mount(
    app: web.Application,
    sessions: dict,
    tools=None,
    *,
    assets: Path | None = None,
    control_policy: str = "",
    pairing_room: str = "",
    pairing_sha256: str = "",
    pairing_store: Path | None = None,
) -> PodViewBridge:
    bridge = PodViewBridge(
        sessions,
        tools,
        assets=assets,
        control_policy=control_policy,
        pairing_room=pairing_room,
        pairing_sha256=pairing_sha256,
        pairing_store=pairing_store,
    )
    app[BRIDGE] = bridge

    async def close_receipts(_app):
        sink = getattr(tools, "podview_receipts", None)
        if sink is not None:
            await sink.aclose()

    app.on_cleanup.append(close_receipts)
    app.add_routes(
        [
            web.get("/view/api/snapshot", _snapshot),
            web.get("/view/api/events", _events),
            web.post("/view/api/actions", _actions),
            web.post("/view/api/control/setup", _control),
            web.post("/view/api/control/actions", _control),
            web.post("/view/api/pair", _pair),
            web.get("/view/api/music", _music),
            web.post("/view/api/music/selection/setup", _music_selection),
            web.post("/view/api/music/selection/actions", _music_selection),
            web.get("/view/api/home", _home),
            web.get("/view/api/answers", _answers),
            web.get("/view/api/sources/{receipt_id}", _answers),
            web.get("/view/", _assets),
            web.get("/view/{asset:.*}", _assets),
        ]
    )
    return bridge

podvoice/gatekeeper/podview_controls.py.source:
"""Explicit administrator-scoped touch tasks over existing device/account owners."""

from __future__ import annotations

import asyncio
import copy
import hashlib
import json
import secrets
import time

from .device_control import EXECUTE_ACTION
from .execution_policy import ExecutionContext
from .podview_vacuum_control import VacuumTransport

_MUSIC = {"pause", "resume", "next", "previous", "volume", "play_track"}
_LABELS = {
    "pause": "Pause",
    "resume": "Afspil",
    "next": "Næste",
    "previous": "Forrige",
    "volume": "Lydstyrke",
}


def policy(value: str) -> dict:
    """Supervisor-owned closed configuration; malformed policy grants nothing."""
    try:
        if len(value) > 8192:
            return {}
        data = json.loads(value)
        if not isinstance(data, dict) or set(data) != {"roomId", "music", "vacuum"}:
            return {}
        if not isinstance(data["roomId"], str) or not 1 <= len(data["roomId"]) <= 160:
            return {}
        for domain in ("music", "vacuum"):
            if not isinstance(data[domain], list) or len(data[domain]) > 8:
                return {}
            seen = set()
            for row in data[domain]:
                required = (
                    {"accountId", "targetId", "actions", "maxVolume"}
                    if domain == "music"
                    else {"entityId", "actions"}
                )
                if not isinstance(row, dict) or set(row) != required:
                    return {}
                keys = ("accountId", "targetId") if domain == "music" else ("entityId",)
                if any(not isinstance(row[k], str) or not 1 <= len(row[k]) <= 1024 for k in keys):
                    return {}
                identity = tuple(row[k] for k in keys)
                if identity in seen:
                    return {}
                seen.add(identity)
                allowed = (
                    _MUSIC
                    if domain == "music"
                    else {"settings", "start", "reuse", "pause", "stop", "return"}
                )
                actions = row["actions"]
                if (
                    not isinstance(actions, list)
                    or not actions
                    or any(not isinstance(a, str) or a not in allowed for a in actions)
                    or len(set(actions)) != len(actions)
                ):
                    return {}
                if domain == "music" and (
                    type(row["maxVolume"]) is not int or not 0 <= row["maxVolume"] <= 100
                ):
                    return {}
                if domain == "vacuum" and not row["entityId"].startswith("vacuum."):
                    return {}
        return data
    except (ValueError, TypeError):
        return {}


def failure(error: str) -> dict:
    return {"ok": False, "error": error, "retryAllowed": False}


class TouchControls:
    def __init__(self, bridge, configuration: str, music) -> None:
        self.bridge, self.music = bridge, music
        self.policy = policy(configuration)
        self.tasks: dict[str, dict] = {}
        self.receipts: dict[tuple, tuple] = {}
        self.busy: set[str] = set()

    def domains(self, room: str, token: str) -> list[str]:
        if self.policy.get("roomId") != room or not self.bridge._grant_current(room, token):
            return []
        result = []
        if (
            any(set(row["actions"]) & (_MUSIC - {"play_track"}) for row in self.policy["music"])
            and self.music.tools is self.bridge.tools
            and self.music.available
        ):
            result.append("music")
        owner = getattr(self.bridge.tools, "_device_control", None)
        if self.policy["vacuum"] and owner is not None and owner.available:
            result.append("vacuum")
        return result

    def selection_allowed(self, room: str, token: str) -> bool:
        return bool(
            self.policy.get("roomId") == room
            and self.bridge._grant_current(room, token)
            and self.music.tools is self.bridge.tools
            and self.music.track_available
            and any("play_track" in row["actions"] for row in self.policy["music"])
        )

    def _binding(self, room: str, domain: str) -> tuple:
        tools = self.bridge.tools
        owner = getattr(tools, "_device_control", None)
        return (
            self.bridge.sessions.get(room),
            tools,
            self.music.binding()
            if domain == "music"
            else (
                owner,
                getattr(owner, "_generation", None),
                getattr(owner, "_client", None),
                getattr(owner, "_token", None),
            ),
        )

    def _current(self, task: dict, token: str) -> bool:
        return bool(
            secrets.compare_digest(task["token"], token)
            and time.monotonic() < task["deadline"]
            and task["domain"] in self.domains(task["room"], token)
            and task["binding"] == self._binding(task["room"], task["domain"])
        )

    def _retire_receipts(self) -> None:
        # Temporary owner unavailability is not terminal: retain those replay fences.
        now = time.monotonic()
        self.receipts = {
            key: value
            for key, value in self.receipts.items()
            if (grant := self.bridge._grants.get(key[0])) is not None
            and secrets.compare_digest(grant[0], key[1])
            and now < grant[-1]
        }

    async def setup(self, body: dict, token: str) -> dict:
        if set(body) - {"bootId", "roomId", "domain", "target", "recipeId"} or not {
            "bootId",
            "roomId",
            "domain",
            "target",
        } <= set(body):
            return failure("invalid_setup")
        room, domain, target = body["roomId"], body["domain"], body["target"]
        if (
            not isinstance(room, str)
            or domain not in ("music", "vacuum")
            or not isinstance(target, dict)
            or body["bootId"] != self.bridge.boot_id
        ):
            return failure("invalid_setup")
        if domain not in self.domains(room, token):
            return failure("scope_not_paired")
        if room in self.busy:
            return failure("busy")
        if domain == "music":
            if (
                set(target) != {"accountId", "kind", "targetId"}
                or target["kind"] != "spotify_device"
                or "recipeId" in body
            ):
                return failure("invalid_target")
            rule = next(
                (
                    r
                    for r in self.policy[domain]
                    if (r["accountId"], r["targetId"]) == (target["accountId"], target["targetId"])
                ),
                None,
            )
        else:
            if set(target) != {"entityId"} or (
                "recipeId" in body
                and (not isinstance(body["recipeId"], str) or not 1 <= len(body["recipeId"]) <= 160)
            ):
                return failure("invalid_target")
            rule = next(
                (r for r in self.policy[domain] if r["entityId"] == target["entityId"]), None
            )
            if "recipeId" in body and rule is not None and "reuse" not in rule["actions"]:
                rule = None
        if rule is None:
            return failure("target_not_granted")
        self._retire_receipts()
        self.tasks = {k: t for k, t in self.tasks.items() if self._current(t, t["token"])}
        if len(self.tasks) >= 64:
            return failure("setup_capacity")
        task_id = "control:" + secrets.token_hex(16)
        task = {
            "room": room,
            "domain": domain,
            "token": token,
            "binding": self._binding(room, domain),
            "deadline": time.monotonic() + 120,
            "options": {},
            "consumed": False,
            "target": target,
            "rule": rule,
        }

        def current():
            return self._current(task, token)

        self.busy.add(room)
        try:
            async with asyncio.timeout(10):
                if domain == "music":
                    offered = await self.music.setup(
                        target["accountId"], target["targetId"], current
                    )
                    if offered.get("ok") is not True or not current():
                        return failure("setup_unavailable")
                    task["offered"] = offered["data"]
                    task["deadline"] = min(
                        task["deadline"],
                        time.monotonic() + max(0, offered["data"]["valid_until"] - time.time()),
                    )
                    public_options = []
                    for action in offered["data"]["actions"]:
                        if action == "play_track":
                            continue  # Selected tracks use the separate source-bound task.
                        if action not in rule["actions"]:
                            continue
                        oid = secrets.token_hex(12)
                        schema = (
                            {"kind": "percent", "min": 0, "max": rule["maxVolume"]}
                            if action == "volume"
                            else {"kind": "none"}
                        )
                        task["options"][oid] = {"action": action, "schema": schema}
                        public_options.append(
                            {
                                "id": oid,
                                "label": _LABELS[action],
                                "action": action,
                                "argsSchema": schema,
                            }
                        )
                    setup = {"volume": offered["data"]["volume_percent"]}
                else:
                    device = self.bridge.tools._device_control
                    task["owner"] = ("podview:" + self.bridge.boot_id, task_id)
                    active = None
                    if (
                        set(rule["actions"]) & {"pause", "stop", "return"}
                        and "recipeId" not in body
                    ):
                        facade = VacuumTransport(device)
                        active = await facade.setup(target["entityId"], current)
                    public_options = []
                    setup = {"mapName": None}
                    if active is not None:
                        task["vacuum_transport"] = facade
                        task["vacuum_transport_offer"] = active
                        task["deadline"] = min(task["deadline"], active["deadline"])
                        for action in active["actions"]:
                            if action not in rule["actions"]:
                                continue
                            oid = secrets.token_hex(12)
                            schema = {"kind": "none"}
                            task["options"][oid] = {
                                "action": action,
                                "schema": schema,
                                "native": True,
                            }
                            public_options.append(
                                {
                                    "id": oid,
                                    "label": {
                                        "pause": "Pause rengøring",
                                        "stop": "Stop rengøring",
                                        "return": "Til basen",
                                    }[action],
                                    "action": action,
                                    "argsSchema": schema,
                                }
                            )
                    if (active is None or active["state"] in {"idle", "docked"}) and (
                        set(rule["actions"]) & {"settings", "start"} or "recipeId" in body
                    ):
                        try:
                            offered = await device.display_setup(
                                target["entityId"], task["owner"], body.get("recipeId")
                            )
                        except Exception:
                            if not public_options:
                                raise
                        else:
                            if not current():
                                return failure("stale_setup")
                            task["offered"] = offered
                            public_options += self._robot_options(task, "recipeId" in body)
                            setup = {"mapName": offered["data"]["map"]["name"]}
            if not current():
                return failure("stale_setup")
            self.tasks[task_id] = task
            return {
                "ok": True,
                "schema": "podview.control.v1",
                "roomId": room,
                "bootId": self.bridge.boot_id,
                "taskId": task_id,
                "revision": 1,
                "expiresAt": time.time() + max(0, task["deadline"] - time.monotonic()),
                "domain": domain,
                "options": public_options,
                "setup": setup,
            }
        except Exception:
            return failure("setup_unavailable")
        finally:
            self.busy.discard(room)

    def _robot_options(self, task: dict, reuse: bool) -> list[dict]:
        data, rule = task["offered"]["data"], task["rule"]
        rows = []

        def add(label, action, schema, internal):
            oid = secrets.token_hex(12)
            task["options"][oid] = {"action": action, "schema": schema, **internal}
            rows.append({"id": oid, "label": label, "action": action, "argsSchema": schema})

        if reuse:
            add(
                "Brug denne rengøring",
                "reuse",
                {"kind": "none"},
                {"steps": task["offered"]["steps"]},
            )
            return rows
        if "settings" in rule["actions"]:
            settings = [
                (r["entity_id"], "select.select_option", r["role"], r["options"])
                for r in data["controls"]
            ]
            if data["fan_speed_options"]:
                settings.append(
                    (
                        data["entity_id"],
                        "vacuum.set_fan_speed",
                        "Sugestyrke",
                        data["fan_speed_options"],
                    )
                )
            labels = {
                "cleaning_mode": "Rengøringstype",
                "mop_intensity": "Vandmængde",
                "mop_mode": "Moppetilstand",
            }
            for entity, action, role, values in settings:
                choices = {secrets.token_hex(12): value for value in values}
                add(
                    labels.get(role, role),
                    "set_option",
                    {
                        "kind": "choice",
                        "choices": [{"id": key, "label": value} for key, value in choices.items()],
                    },
                    {"entity": entity, "service": action, "choices": choices},
                )
        if "start" in rule["actions"]:
            areas = {secrets.token_hex(12): row for row in data["map"]["areas"]}
            if areas:
                add(
                    "Start rengøring",
                    "start",
                    {
                        "kind": "cleaning",
                        "areas": [{"id": key, "label": row["name"]} for key, row in areas.items()],
                        "repeat": {"min": 1, "max": 3},
                    },
                    {"areas": areas},
                )
        return rows

    async def action(self, body: dict, token: str) -> dict:
        if (
            set(body) != {"bootId", "roomId", "taskId", "revision", "requestId", "optionId", "args"}
            or any(
                not isinstance(body[k], str) for k in ("roomId", "taskId", "requestId", "optionId")
            )
            or not 1 <= len(body["requestId"]) <= 120
            or not isinstance(body["args"], dict)
        ):
            return failure("invalid_action")
        task = self.tasks.get(body["taskId"])
        if task is None or not self._current(task, token) or body["roomId"] != task["room"]:
            return failure("stale_action")
        fingerprint = hashlib.sha256(json.dumps(body, sort_keys=True).encode()).hexdigest()
        self._retire_receipts()
        key = (task["room"], token, body["requestId"])
        if key in self.receipts:
            previous, receipt = self.receipts[key]
            return copy.deepcopy(receipt) if previous == fingerprint else failure("request_reused")
        if (
            body["bootId"] != self.bridge.boot_id
            or type(body["revision"]) is not int
            or body["revision"] != 1
            or task["consumed"]
        ):
            return failure("stale_action")
        option = task["options"].get(body["optionId"])
        if option is None:
            return failure("unknown_option")
        args = body["args"]
        try:
            steps = self._steps(task, option, args)
        except (KeyError, ValueError, TypeError):
            return failure("invalid_arguments")
        if task["room"] in self.busy:
            return failure("busy")
        if len(self.receipts) >= 1024:
            return failure("request_capacity")
        receipt = {
            "ok": False,
            "requestId": body["requestId"],
            "outcome": "unknown",
            "retryAllowed": False,
            "physicalResultVerified": False,
        }
        task["consumed"] = True
        self.receipts[key] = fingerprint, receipt
        self.busy.add(task["room"])

        def current():
            return self._current(task, token)

        try:
            async with asyncio.timeout(30):
                if task["domain"] == "music":
                    result = await self.music.execute(
                        task["offered"], option["action"], args, current
                    )
                    outcome = result.get("outcome", "unknown")
                elif option.get("native") is True:
                    outcome = await task["vacuum_transport"].execute(
                        task["vacuum_transport_offer"], option["action"], current
                    )
                else:
                    capability = task["offered"]["capability_token"]
                    outcome = "rejected"
                    for step in steps:
                        if not current():
                            outcome = "unknown"
                            break
                        outcome = "unknown"
                        result = await self.bridge.tools.dispatch(
                            EXECUTE_ACTION,
                            {"capability_token": capability, **step},
                            execution_context=ExecutionContext(*task["owner"]),
                            execution_guard=current,
                        )
                        if result.get("ok") is not True:
                            break
                        outcome = "accepted"
                        capability = result.get("capability_token")
                        if step is not steps[-1] and not isinstance(capability, str):
                            outcome = "unknown"
                            break
                receipt = {
                    **receipt,
                    "ok": outcome == "accepted",
                    "outcome": outcome
                    if outcome in {"accepted", "rejected", "unknown"}
                    else "unknown",
                }
                self.receipts[key] = fingerprint, receipt
        except (Exception, asyncio.CancelledError):
            pass  # Terminal unknown retained; no retry or leaked upstream detail.
        finally:
            self.busy.discard(task["room"])
        return copy.deepcopy(receipt)

    def _steps(self, task: dict, option: dict, args: dict) -> list[dict]:
        kind = option["schema"]["kind"]
        if kind == "none":
            if args:
                raise ValueError
            return option.get("steps", [])
        if kind == "percent":
            if (
                set(args) != {"percent"}
                or type(args["percent"]) is not int
                or not 0 <= args["percent"] <= option["schema"]["max"]
            ):
                raise ValueError
            return []
        if kind == "choice":
            if set(args) != {"choiceId"} or not isinstance(args["choiceId"], str):
                raise ValueError
            value = option["choices"][args["choiceId"]]
            key = "fan_speed" if option["service"] == "vacuum.set_fan_speed" else "option"
            return [
                {
                    "entity_id": option["entity"],
                    "action": option["service"],
                    "arguments": {key: value},
                }
            ]
        if (
            kind != "cleaning"
            or set(args) != {"areaIds", "repeat"}
            or type(args["repeat"]) is not int
            or not 1 <= args["repeat"] <= 3
            or not isinstance(args["areaIds"], list)
            or not 1 <= len(args["areaIds"]) <= 32
            or any(not isinstance(a, str) for a in args["areaIds"])
            or len(set(args["areaIds"])) != len(args["areaIds"])
        ):
            raise ValueError
        areas = [option["areas"][key]["area_id"] for key in args["areaIds"]]
        return [
            {
                "entity_id": task["target"]["entityId"],
                "action": "vacuum.send_command",
                "arguments": {
                    "command": "app_segment_clean",
                    "area_ids": areas,
                    "repeat": args["repeat"],
                },
            }
        ]

podvoice/gatekeeper/podview_music.py.source:
"""Closed display projections of PodConnect's account-owned observation contracts."""

from __future__ import annotations

import json
import re
import time
from datetime import datetime
from typing import Any
from urllib.parse import urlsplit

SERVICES = {
    "playback": "get_playback_snapshot",
    "queue": "get_queue",
    "search": "search_tracks",
}
_ERRORS = frozenset(
    {
        "unavailable",
        "stale",
        "busy",
        "authentication_required",
        "forbidden",
        "rate_limited",
        "malformed_response",
    }
)
_ARTWORK_PATH = re.compile(r"^/image/[A-Za-z0-9_-]{1,128}$")
_TRACK_URI = re.compile(r"^spotify:track:[A-Za-z0-9]{22}$")


def normalize_search_query(value: Any) -> str:
    """Keep search text bounded and literal; it is never interpreted as markup."""
    if not isinstance(value, str):
        raise ValueError("invalid search query")
    query = value.strip()
    if not 1 <= len(query) <= 160:
        raise ValueError("invalid search query")
    return query


def _artwork(value: Any) -> dict | None:
    """Accept only PodConnect's optional Spotify image reference; never arbitrary URLs."""
    if not isinstance(value, dict) or set(value) != {"kind", "provider", "url"}:
        return None
    url = value.get("url")
    if not isinstance(url, str) or not 1 <= len(url) <= 512:
        return None
    try:
        parsed = urlsplit(url)
        if (
            value.get("kind") != "album_cover"
            or value.get("provider") != "spotify"
            or parsed.scheme != "https"
            or parsed.hostname != "i.scdn.co"
            or parsed.username is not None
            or parsed.password is not None
            or parsed.port is not None
            or parsed.query
            or parsed.fragment
            or not _ARTWORK_PATH.fullmatch(parsed.path)
        ):
            return None
    except ValueError:
        return None
    return {"kind": "album_cover", "provider": "spotify", "url": url}


def unavailable(kind: str = "unavailable") -> dict:
    return {"ok": False, "error_kind": kind, "retryAllowed": False}


def _text(value: Any, maximum: int = 1024) -> str:
    if not isinstance(value, str) or not 1 <= len(value) <= maximum:
        raise ValueError("invalid text")
    return value


def _number(value: Any, *, nullable: bool = True) -> int | None:
    if value is None and nullable:
        return None
    if type(value) is not int or not 0 <= value < 2**53:
        raise ValueError("invalid number")
    return value


def _timestamp(value: Any, max_age_ms: int) -> str:
    source = _text(value, 64)
    stamp = datetime.fromisoformat(source)
    if stamp.tzinfo is None or not -5000 <= (time.time() - stamp.timestamp()) * 1000 <= max_age_ms:
        raise ValueError("stale timestamp")
    return source


def _item(value: Any) -> dict | None:
    if value is None:
        return None
    if not isinstance(value, dict) or value.get("type") not in ("track", "episode"):
        raise ValueError("invalid item")
    kind = value["type"]
    uri = _text(value.get("uri"))
    if not uri.startswith(f"spotify:{kind}:") or not uri.removeprefix(f"spotify:{kind}:"):
        raise ValueError("invalid uri")
    artists = value.get("artists")
    if not isinstance(artists, list) or len(artists) > 20:
        raise ValueError("invalid artists")
    projected = {
        "type": kind,
        "uri": uri,
        "name": _text(value.get("name")),
        "artists": [_text(v) for v in artists],
        "duration_ms": _number(value.get("duration_ms")),
    }
    if kind == "track":
        artwork = _artwork(value.get("artwork"))
        if artwork is not None:
            projected["artwork"] = artwork
    return projected


def project_owner(kind: str, value: Any, account: str | None, *, query: str | None = None) -> dict:
    """Preserve source provenance, copying only fields admitted by the v1 contracts."""
    try:
        _text(account)
        if kind not in SERVICES or not isinstance(value, dict):
            return unavailable()
        if value.get("ok") is not True:
            error = value.get("error_kind")
            return unavailable(
                error if isinstance(error, str) and error in _ERRORS else "unavailable"
            )
        expected_schema = (
            "podconnect.search_tracks.v1" if kind == "search" else f"podconnect.{kind}.v1"
        )
        if value.get("config_entry_id") != account or value.get("schema") != expected_schema:
            raise ValueError("wrong account or schema")
        if kind == "search":
            expected_query = normalize_search_query(query)
            actual_query = normalize_search_query(value.get("query"))
            limit = value.get("limit")
            rows = value.get("tracks")
            if (
                actual_query != expected_query
                or value.get("source") != "spotify_web_api"
                or value.get("coverage") != "spotify_search_sample"
                or type(limit) is not int
                or limit != 3
                or not isinstance(rows, list)
                or len(rows) > limit
                or type(value.get("source_sample_count")) is not int
                or value["source_sample_count"] != len(rows)
                or type(value.get("returned_count")) is not int
                or value["returned_count"] != len(rows)
                or (
                    value.get("source_has_more") is not None
                    and type(value.get("source_has_more")) is not bool
                )
            ):
                raise ValueError("invalid search sample")
            tracks = []
            for row in rows:
                if not isinstance(row, dict) or set(row) - {"name", "artist", "uri", "artwork"}:
                    raise ValueError("invalid search track")
                track: dict[str, Any] = {
                    "name": _text(row.get("name"), 256),
                    "artist": _text(row.get("artist"), 512),
                    "uri": _text(row.get("uri"), 64),
                }
                if not _TRACK_URI.fullmatch(track["uri"]):
                    raise ValueError("invalid search URI")
                artwork = _artwork(row.get("artwork"))
                if artwork is not None:
                    track["artwork"] = artwork
                tracks.append(track)
            search_result: dict[str, Any] = {
                "ok": True,
                "data": {
                    "ok": True,
                    "schema": value["schema"],
                    "config_entry_id": account,
                    "source": "spotify_web_api",
                    "query": actual_query,
                    "coverage": "spotify_search_sample",
                    "limit": limit,
                    "source_sample_count": len(tracks),
                    "returned_count": len(tracks),
                    "source_has_more": value["source_has_more"],
                    "tracks": tracks,
                },
            }
            if len(json.dumps(search_result, allow_nan=False).encode()) > 65536:
                raise ValueError("search response exceeds budget")
            return search_result
        epoch = _text(value.get("owner_epoch"), 128)
        result: dict[str, Any] = {
            "ok": True,
            "schema": value["schema"],
            "config_entry_id": account,
            "owner_epoch": epoch,
        }
        if kind == "playback":
            sequence = _number(value.get("poll_sequence"), nullable=False)
            if (
                sequence is None
                or sequence < 1
                or value.get("physical_result_verified") is not False
            ):
                raise ValueError("missing poll provenance")
            observation = value.get("observation")
            if (
                not isinstance(observation, dict)
                or observation.get("status") != "fresh"
                or observation.get("source") != "spotify_web_api"
            ):
                raise ValueError("missing observation")
            maximum = _number(observation.get("max_age_ms"), nullable=False)
            age = _number(observation.get("age_ms"), nullable=False)
            if maximum is None or age is None or not 0 < maximum <= 15000 or age > maximum:
                return unavailable("stale")
            stamp = _timestamp(observation.get("observed_at"), maximum)
            playback = value.get("playback")
            if not isinstance(playback, dict):
                raise ValueError("missing playback")
            state = playback.get("state")
            projected: dict[str, Any]
            if state == "no_active_playback":
                if playback.get("target") is not None or playback.get("item") is not None:
                    raise ValueError("contradictory empty playback")
                projected = {"state": state, "target": None, "item": None}
            elif state in ("playing", "paused"):
                target = playback.get("target")
                if target is not None:
                    if not isinstance(target, dict) or target.get("kind") != "spotify_device":
                        raise ValueError("invalid target")
                    target = {
                        "kind": "spotify_device",
                        "target_id": _text(target.get("target_id")),
                        "name": None if target.get("name") is None else _text(target["name"]),
                    }
                shuffle, repeat = playback.get("shuffle"), playback.get("repeat")
                if (shuffle is not None and type(shuffle) is not bool) or repeat not in (
                    None,
                    "off",
                    "track",
                    "context",
                ):
                    raise ValueError("invalid controls observation")
                projected = {
                    "state": state,
                    "target": target,
                    "item": _item(playback.get("item")),
                    "progress_ms": _number(playback.get("progress_ms")),
                    "provider_changed_at_ms": _number(playback.get("provider_changed_at_ms")),
                    "shuffle": shuffle,
                    "repeat": repeat,
                }
            else:
                raise ValueError("unsupported state")
            result.update(
                poll_sequence=sequence,
                observation={
                    "status": "fresh",
                    "observed_at": stamp,
                    "age_ms": age,
                    "max_age_ms": maximum,
                    "source": "spotify_web_api",
                },
                playback=projected,
                physical_result_verified=False,
            )
        else:
            snapshot = _text(value.get("snapshot_id"), 256)
            if not snapshot.startswith(epoch + ":queue:"):
                raise ValueError("wrong queue owner")
            if (
                value.get("scope") != "account"
                or value.get("coverage") != "provider_response"
                or value.get("relation_to_playback") != "not_atomic"
            ):
                raise ValueError("invalid queue coverage")
            rows = value.get("items")
            if (
                not isinstance(rows, list)
                or len(rows) > 20
                or type(value.get("returned_count")) is not int
                or value["returned_count"] != len(rows)
                or type(value.get("truncated")) is not bool
            ):
                raise ValueError("invalid queue")
            items = []
            for index, row in enumerate(rows):
                item = _item(row)
                if item is None or row.get("option_id") != f"{snapshot}:{index}":
                    raise ValueError("invalid occurrence identity")
                items.append({"option_id": row["option_id"], **item})
            result.update(
                snapshot_id=snapshot,
                observed_at=_timestamp(value.get("observed_at"), 15000),
                scope="account",
                coverage="provider_response",
                relation_to_playback="not_atomic",
                currently_playing=_item(value.get("currently_playing")),
                items=items,
                returned_count=len(items),
                truncated=value["truncated"],
            )
        if len(json.dumps(result, allow_nan=False).encode()) > 65536:
            raise ValueError("response exceeds budget")
        return {"ok": True, "data": result}
    except (ValueError, TypeError, KeyError, OverflowError):
        return unavailable("malformed_response")

podvoice/gatekeeper/podview_music_contro.source:
"""Scoped direct-device transport through the existing PodConnect command owner.

The HTTP broker owns paired room/action/volume permission and keeps offers server-side.
Its current callback must also bind the original setup's facade binding. This module
never discovers services, chooses targets, retries commands or owns provider secrets.
"""

from __future__ import annotations

import asyncio
import json
import math
import re
import time
from collections.abc import Callable
from datetime import datetime
from typing import Any

from . import constants as C

_TIMEOUT_S = 8
_MAX_BYTES = 65536
_SERVICES = frozenset({"get_playback_controls", "control_playback"})
_ACTIONS = frozenset({"pause", "resume", "next", "previous", "volume", "play_track"})
_ERRORS = frozenset(
    {
        "unavailable",
        "stale",
        "busy",
        "authentication_required",
        "forbidden",
        "rate_limited",
        "malformed_response",
        "owner_replaced",
        "target_not_current",
        "invalid_target",
        "capabilities_unavailable",
        "invalid_arguments",
        "stale_owner",
        "invalid_request_identity",
        "request_reused",
        "stale_command",
        "command_sequence_gap",
        "stale_observation",
        "awaiting_observation",
        "unsupported_action",
        "volume_above_approved_limit",
        "outcome_unknown",
    }
)


def _text(value: Any, maximum: int = 1024) -> str:
    if not isinstance(value, str) or not 1 <= len(value) <= maximum:
        raise ValueError("invalid identifier")
    return value


def _integer(value: Any, minimum: int = 1, maximum: int = 2**53 - 1) -> int:
    if type(value) is not int or not minimum <= value <= maximum:
        raise ValueError("invalid integer")
    return value


def _controls(value: Any, account: str, target: str, *, offered: bool = False) -> dict:
    if (
        not isinstance(value, dict)
        or value.get("ok") is not True
        or value.get("schema") != "podconnect.controls.v1"
        or value.get("config_entry_id") != account
        or value.get("physical_result_verified") is not False
    ):
        raise ValueError("invalid owner controls")
    epoch = _text(value.get("owner_epoch"), 128)
    poll = _integer(value.get("poll_sequence"))
    status = value.get("status")
    if status not in {"ready", "awaiting_observation", "sequence_exhausted"}:
        raise ValueError("invalid owner status")
    sequence = value.get("next_command_sequence")
    if status == "sequence_exhausted":
        if sequence is not None:
            raise ValueError("invalid exhausted sequence")
    else:
        sequence = _integer(sequence)
    destination = value.get("target")
    if (
        not isinstance(destination, dict)
        or destination.get("kind") != "spotify_device"
        or destination.get("target_id") != target
    ):
        raise ValueError("wrong target")
    name = destination.get("name")
    if name is not None:
        name = _text(name)
    observation = value.get("observation")
    if (
        not isinstance(observation, dict)
        or observation.get("source") != "spotify_web_api"
        or observation.get("status") != "fresh"
    ):
        raise ValueError("missing source")
    maximum = _integer(observation.get("max_age_ms"), 1, 15000)
    age = _integer(observation.get("age_ms"), 0, maximum)
    timestamp = _text(observation.get("observed_at"), 64)
    stamp = datetime.fromisoformat(timestamp)
    now = time.time()
    if stamp.tzinfo is None or not -5 <= now - stamp.timestamp() < maximum / 1000:
        raise ValueError("stale source")
    deadline = min(stamp.timestamp() + maximum / 1000, now + (maximum - age) / 1000)
    if offered:
        fixed: Any = value.get("valid_until")
        if type(fixed) not in (int, float) or not math.isfinite(fixed) or fixed > deadline:
            raise ValueError("invalid offer deadline")
        deadline = fixed
    if deadline <= now:
        raise ValueError("expired source")
    actions = value.get("actions")
    if (
        not isinstance(actions, list)
        or len(actions) > 6
        or any(not isinstance(action, str) or action not in _ACTIONS for action in actions)
        or len(set(actions)) != len(actions)
        or {"pause", "resume"}.issubset(actions)
        or (status != "ready" and actions)
    ):
        raise ValueError("invalid actions")
    volume = value.get("volume_percent")
    if volume is not None:
        volume = _integer(volume, 0, 100)
    if "volume" in actions and volume is None:
        raise ValueError("unobserved volume capability")
    track_play_supported = value.get("track_play_supported") is True
    return {
        "ok": True,
        "schema": "podconnect.controls.v1",
        "config_entry_id": account,
        "owner_epoch": epoch,
        "poll_sequence": poll,
        "next_command_sequence": sequence,
        "target": {"kind": "spotify_device", "target_id": target, "name": name},
        "observation": {
            "status": "fresh",
            "source": "spotify_web_api",
            "observed_at": timestamp,
            "age_ms": age,
            "max_age_ms": maximum,
        },
        "actions": list(actions),
        "volume_percent": volume,
        "track_play_supported": track_play_supported,
        "status": status,
        "valid_until": deadline,
        "physical_result_verified": False,
    }


def _failure(kind: str, *, possible_send: bool = False, identity: dict | None = None) -> dict:
    return {
        **(identity or {}),
        "ok": False,
        "outcome": "unknown" if possible_send else "rejected",
        "error_kind": "outcome_unknown" if possible_send else kind,
        "provider_request_accepted": False,
        "retry_allowed": False,
        "physical_result_verified": False,
    }


def _receipt(value: Any, identity: dict) -> dict:
    if not isinstance(value, dict):
        raise ValueError("invalid receipt")
    _integer(value.get("command_sequence"))
    if not isinstance(value, dict) or any(
        value.get(key) != expected for key, expected in identity.items()
    ):
        raise ValueError("mismatched receipt")
    outcome = value.get("outcome")
    accepted = outcome == "accepted"
    if (
        outcome not in {"accepted", "unknown", "rejected"}
        or value.get("ok") is not accepted
        or value.get("provider_request_accepted") is not accepted
        or value.get("retry_allowed") is not False
        or value.get("physical_result_verified") is not False
    ):
        raise ValueError("invalid receipt")
    result = {
        **identity,
        "ok": accepted,
        "outcome": outcome,
        "provider_request_accepted": accepted,
        "retry_allowed": False,
        "physical_result_verified": False,
    }
    if "observe_after_poll_sequence" in value:
        result["observe_after_poll_sequence"] = _integer(value["observe_after_poll_sequence"], 0)
    if not accepted:
        kind = value.get("error_kind")
        result["error_kind"] = kind if isinstance(kind, str) and kind in _ERRORS else "unavailable"
    return result


class MusicControlFacade:
    """A bounded transport, never a grant or a second command owner."""

    def __init__(self, tools: Any) -> None:
        self.tools = tools

    @property
    def available(self) -> bool:
        try:
            token = getattr(self.tools, "_token", None)
            client = getattr(self.tools, "_client", None)
            discovery = getattr(self.tools, "_discovery", None)
            return bool(
                isinstance(token, str)
                and token
                and client is not None
                and getattr(client, "is_closed", None) is False
                and _SERVICES <= getattr(discovery, "podconnect_services", frozenset())
                and callable(getattr(self.tools, "podview_music_binding", None))
            )
        except Exception:
            return False

    @property
    def track_available(self) -> bool:
        return bool(
            self.available
            and "get_track_play_controls"
            in getattr(getattr(self.tools, "_discovery", None), "podconnect_services", frozenset())
        )

    def binding(self) -> tuple:
        try:
            if self.available:
                return (id(self.tools), *self.tools.podview_music_binding(), True)
        except Exception:
            pass
        return (id(self.tools), None, False)

    def _current(self, binding: tuple, current: Callable[[], bool]) -> bool:
        try:
            return (
                binding[-1] is True
                and self.available
                and binding == self.binding()
                and bool(current())
            )
        except Exception:
            return False

    async def _read(self, client: Any, token: str, service: str, args: dict) -> Any:
        async with client.stream(
            "POST",
            f"{C.SUPERVISOR_CORE_API}/services/podconnect/{service}?return_response",
            headers={"Authorization": f"Bearer {token}"},
            json=args,
            follow_redirects=False,
        ) as response:
            if response.status_code != 200:
                raise ValueError("service unavailable")
            raw = bytearray()
            async for chunk in response.aiter_bytes(8192):
                raw.extend(chunk)
                if len(raw) > _MAX_BYTES:
                    raise ValueError("response too large")
        payload = json.loads(raw)
        return payload.get("service_response") if isinstance(payload, dict) else None

    async def setup(self, account: str, target: str, current: Callable[[], bool]) -> dict:
        try:
            _text(account)
            _text(target)
            binding = self.binding()
            client, token = self.tools._client, self.tools._token
            if not self._current(binding, current):
                return _failure("unavailable")
            async with asyncio.timeout(_TIMEOUT_S):
                result = await self._read(
                    client,
                    token,
                    "get_playback_controls",
                    {
                        "config_entry_id": account,
                        "kind": "spotify_device",
                        "target_id": target,
                    },
                )
            if not self._current(binding, current):
                return _failure("owner_replaced")
            return {"ok": True, "data": _controls(result, account, target)}
        except Exception:
            return _failure("unavailable")

    async def setup_track(self, account: str, target: str, current: Callable[[], bool]) -> dict:
        """Read an exact fresh device and known volume from the provider owner."""
        try:
            _text(account)
            _text(target)
            if not self.track_available:
                return _failure("unavailable")
            binding = self.binding()
            client, token = self.tools._client, self.tools._token
            if not self._current(binding, current):
                return _failure("unavailable")
            async with asyncio.timeout(_TIMEOUT_S):
                result = await self._read(
                    client,
                    token,
                    "get_track_play_controls",
                    {"config_entry_id": account, "kind": "spotify_device", "target_id": target},
                )
            if not self._current(binding, current):
                return _failure("owner_replaced")
            data = _controls(result, account, target)
            if not data["track_play_supported"] or data["actions"] != ["play_track"]:
                return _failure("unsupported_action")
            return {"ok": True, "data": data}
        except Exception:
            return _failure("unavailable")

    async def execute(
        self, offered: dict, action: str, args: dict, current: Callable[[], bool]
    ) -> dict:
        possible_send = False
        identity: dict = {}
        try:
            account = _text(offered.get("config_entry_id"))
            target = _text(offered.get("target", {}).get("target_id"))
            value = _controls(offered, account, target, offered=True)
            if value["status"] != "ready" or action not in value["actions"]:
                return _failure("unsupported_action")
            if not isinstance(args, dict) or set(args) != (
                {"percent"} if action == "volume" else set()
            ):
                return _failure("invalid_arguments")
            if action == "volume":
                _integer(args["percent"], 0, 100)
            sequence, epoch = value["next_command_sequence"], value["owner_epoch"]
            identity = {
                "schema": "podconnect.command.v1",
                "config_entry_id": account,
                "owner_epoch": epoch,
                "request_id": f"{epoch}:{sequence}",
                "command_sequence": sequence,
                "action": action,
                "target": {"kind": "spotify_device", "target_id": target},
            }
            request = {
                "config_entry_id": account,
                "kind": "spotify_device",
                "target_id": target,
                "owner_epoch": epoch,
                "expected_poll_sequence": value["poll_sequence"],
                "request_id": identity["request_id"],
                "command_sequence": sequence,
                "action": action,
                "args": dict(args),
            }
            binding = self.binding()
            client, token = self.tools._client, self.tools._token
            async with asyncio.timeout(_TIMEOUT_S):
                if not self._current(binding, current):
                    return _failure("owner_replaced", identity=identity)
                possible_send = True  # No await between this guard and the sole POST.
                result = await self._read(client, token, "control_playback", request)
            if not self._current(binding, current):
                return _failure("owner_replaced", possible_send=True, identity=identity)
            return _receipt(result, identity)
        except (Exception, asyncio.CancelledError):
            return _failure("unavailable", possible_send=possible_send, identity=identity)

    async def execute_track(
        self, controls: dict, uri: str, max_volume: int, current: Callable[[], bool]
    ) -> dict:
        """Send a broker-selected track once through the same exact device owner."""
        possible_send = False
        identity: dict = {}
        try:
            account = _text(controls.get("config_entry_id"))
            target = _text(controls.get("target", {}).get("target_id"))
            value = _controls(controls, account, target, offered=True)
            if (
                value["status"] != "ready"
                or not value["track_play_supported"]
                or value["actions"] != ["play_track"]
            ):
                return _failure("unsupported_action")
            if (
                not isinstance(uri, str)
                or re.fullmatch(r"spotify:track:[A-Za-z0-9]{22}", uri) is None
            ):
                return _failure("invalid_arguments")
            if (
                type(max_volume) is not int
                or not 0 <= max_volume <= 100
                or value["volume_percent"] is None
                or value["volume_percent"] > max_volume
            ):
                return _failure("volume_above_approved_limit")
            sequence, epoch = value["next_command_sequence"], value["owner_epoch"]
            identity = {
                "schema": "podconnect.command.v1",
                "config_entry_id": account,
                "owner_epoch": epoch,
                "request_id": f"{epoch}:{sequence}",
                "command_sequence": sequence,
                "action": "play_track",
                "target": {"kind": "spotify_device", "target_id": target},
            }
            request = {
                "config_entry_id": account,
                "kind": "spotify_device",
                "target_id": target,
                "owner_epoch": epoch,
                "expected_poll_sequence": value["poll_sequence"],
                "request_id": identity["request_id"],
                "command_sequence": sequence,
                "action": "play_track",
                "args": {"track_uri": uri, "max_volume": max_volume},
            }
            binding = self.binding()
            client, token = self.tools._client, self.tools._token
            async with asyncio.timeout(_TIMEOUT_S):
                if not self._current(binding, current):
                    return _failure("owner_replaced", identity=identity)
                possible_send = True
                result = await self._read(client, token, "control_playback", request)
            if not self._current(binding, current):
                return _failure("owner_replaced", possible_send=True, identity=identity)
            return _receipt(result, identity)
        except (Exception, asyncio.CancelledError):
            return _failure("unavailable", possible_send=possible_send, identity=identity)

podvoice/gatekeeper/podview_receipts.py.source:
"""Bounded completed-tool receipts; no URLs, generated facts or provider calls.

The conversation owner offers only successfully submitted current results. This
optional sink never awaits speech work. Public routes must enforce ingress/room
access before looking up the opaque receipt IDs. No status-log inference.
"""

from __future__ import annotations

import asyncio
import copy
import math
import secrets
import time
from collections.abc import Callable
from datetime import datetime

from .podview_enrichment import VisualSelector
from .podview_weather import MAX_CURRENT_AGE_S, MAX_RETRIEVAL_AGE_S, weather_projection


def _text(value: object, maximum: int) -> bool:
    return isinstance(value, str) and 0 < len(value) <= maximum


def _weather_result(response: dict) -> dict:
    """Decode only the exact loss-aware owner packing; absent values stay absent."""
    data = response.get("data")
    result = data.get("result") if isinstance(data, dict) else None
    packed = result.get("forecast") if isinstance(result, dict) else None
    if not isinstance(packed, dict):
        return response
    assert isinstance(data, dict) and isinstance(result, dict)
    columns, rows = packed.get("columns"), packed.get("rows")
    if (
        packed.get("format") != "columnar; null means absent or null; no values inferred"
        or packed.get("coverage") != "Only listed timestamps; continuity is not implied."
        or not isinstance(columns, list)
        or not 1 <= len(columns) <= 32
        or not all(_text(c, 64) for c in columns)
        or len(set(columns)) != len(columns)
        or "datetime" not in columns
        or not isinstance(rows, list)
        or not 1 <= len(rows) <= 512
        or type(packed.get("total_rows")) is not int
        or not len(rows) <= packed["total_rows"] <= 512
        or type(packed.get("returned_rows")) is not int
        or packed["returned_rows"] != len(rows)
        or type(packed.get("truncated")) is not bool
        or packed["truncated"] != (len(rows) < packed["total_rows"])
        or any(not isinstance(row, list) or len(row) != len(columns) for row in rows)
    ):
        return {}
    decoded = [
        {key: value for key, value in zip(columns, row, strict=True) if value is not None}
        for row in rows
    ]
    if packed.get("coverage_start") != decoded[0].get("datetime") or packed.get(
        "coverage_end"
    ) != decoded[-1].get("datetime"):
        return {}
    return {**response, "data": {**data, "result": {**result, "forecast": decoded}}}


def _facts(tool_name: str, result: object) -> tuple[str, list[dict], bool, dict] | None:
    if not isinstance(result, dict) or result.get("ok") is not True:
        return None
    if tool_name in {"weather_forecast", "HassGetWeather"}:
        projected = weather_projection(_weather_result(result))
        if projected["status"] != "observed":
            return None
        data = projected["data"]
        facts = []
        current = data["current"]
        if current and current["temperature"] is not None:
            facts.append(
                {
                    "label": "Temperatur",
                    "value": f"{current['temperature']} {data['units']['temperature']}",
                    "detail": "Aktuel måling",
                }
            )
        if current and current["condition"] is not None:
            facts.append(
                {"label": "Vejrforhold", "value": current["condition"], "detail": "Aktuel måling"}
            )
        if not facts:
            return None
        provenance = {
            "kind": "ha_weather",
            "source": data["source"],
            "retrievedAt": data["retrievedAt"],
            "stateUpdatedAt": data["stateUpdatedAt"],
            "validUntil": min(
                datetime.fromisoformat(data["retrievedAt"]).timestamp() + MAX_RETRIEVAL_AGE_S,
                datetime.fromisoformat(data["stateUpdatedAt"]).timestamp() + MAX_CURRENT_AGE_S,
            ),
        }
        return f"Vejret i {data['location']}", facts, False, provenance
    if tool_name == "google_web_sogning":
        data = result.get("data")
        if isinstance(data, dict):
            if data.get("success") is not True:
                return None
            data = data.get("result")
        if isinstance(data, (int, float)) and not isinstance(data, bool) and math.isfinite(data):
            data = str(data)
        if not _text(data, 80):
            return None
        # A scalar does not gain invented context, citations or automatic visual value.
        return (
            "Resultat fra webopslaget",
            [
                {
                    "label": "Svar",
                    "value": data,
                    "detail": "Ekstern kildehenvisning blev ikke leveret",
                }
            ],
            False,
            {"kind": "tool_result"},
        )
    return None


class VisualReceiptOwner:
    """Owner-bound, bounded optional sink. Caller closes it with the add-on owner."""

    def __init__(self, *, clock: Callable[[], float] = time.monotonic) -> None:
        self._clock = clock
        self._rooms: dict[str, dict] = {}
        self._closed = False
        self._selector: VisualSelector | None = None
        self._selection: asyncio.Task | None = None
        self._research_mode = False
        self._research_admitted = False

    def configure_selector(self, selector: VisualSelector | None) -> None:
        """Startup-only optional provider. No browser request can enable it."""
        if self._rooms or self._closed:
            raise RuntimeError("visual selector configuration is startup-only")
        self._selector = selector

    def configure_research_mode(self, policy: str = "") -> None:
        """Supervisor-only startup opt-in; empty default preserves exact26 scope.

        Reuses already-paid completed conversation tool data and the same selector
        allowance. This expands selector purpose and needs separate authorization.
        It never enables background Google calls or another conversation/model.
        """
        if self._rooms or self._closed:
            raise RuntimeError("research presentation configuration is startup-only")
        self._research_mode = policy == "completed_receipts_v1"
        self._research_admitted = self._research_mode and self.selection_enabled

    @property
    def research_admitted(self) -> bool:
        """Already-admitted receipt format survives finite selector exhaustion."""
        return self._research_admitted and not self._closed

    @property
    def research_enabled(self) -> bool:
        return self._research_mode and self.selection_enabled

    @property
    def selection_enabled(self) -> bool:
        return bool(self._selector is not None and self._selector.available and not self._closed)

    async def _select(self, room_id: str, state: dict, row: dict) -> None:
        selector = self._selector
        if selector is None:
            return
        try:
            current = self._current(room_id)
            if current is not state or row not in state["items"]:
                return
            deadline = self._clock() + 5
            revision = state["revision"]

            def current_receipt() -> bool:
                current = self._current(room_id)
                return (
                    current is state
                    and row in state["items"]
                    and state["revision"] == revision
                    and self._clock() < deadline
                )

            async with asyncio.timeout(5):
                selected = await selector.select(
                    copy.deepcopy(row.get("selection_content", row["item"]["content"])),
                    current=current_receipt,
                )

            current = self._current(room_id)
            if (
                current is not state
                or row not in state["items"]
                or not selected
                or not current_receipt()
            ):
                return
            content = row.get("selection_content", row["item"]["content"])
            chosen = selected.get("content", {}).get("facts", [])
            # Independent owner closure: no provider fact can be added or edited.
            if not chosen or any(f not in content["facts"] for f in chosen):
                return
            ids = [f["id"] for f in chosen]
            if len(set(ids)) != len(ids):
                return
            source_ids = {f["sourceId"] for f in chosen}
            selected_sources = [s for s in content["sources"] if s["id"] in source_ids]
            if row["item"]["family"] == "answer-timeline":
                # Model chooses only immutable candidate IDs; owner copies source
                # periods in original chronology, never model prose or timestamps.
                events = [e for e in row["item"]["content"]["events"] if e["id"] in ids]
                row["item"]["content"] = {
                    "summary": content["summary"],
                    "events": events,
                    "sources": selected_sources,
                }
                provenance = row["item"]["provenance"]
                provenance.update(
                    displayedPeriods=len(events),
                    displayedStart=events[0]["time"],
                    displayedEnd=events[-1]["time"],
                )
            else:
                row["item"]["content"] = {
                    "summary": content["summary"],
                    "facts": copy.deepcopy(chosen),
                    "sources": selected_sources,
                }
            row["item"]["displaySuggested"] = True
            state["revision"] += 1
        except (Exception, asyncio.CancelledError):
            return  # Optional display cannot change ACK, playback, close or rearm.

    def offer(
        self,
        owner: object,
        *,
        room_id: str,
        session_id: str,
        session_epoch: float,
        turn_id: str,
        provider_generation: int | None,
        task_id: str,
        input_revision: int,
        call_id: str,
        tool_name: str,
        result: object,
        current: Callable[[], bool],
    ) -> bool:
        """Offer after result submission; no coroutine, network request or retry."""
        if self._closed or not all(
            _text(x, 160) for x in (room_id, session_id, turn_id, task_id, call_id)
        ):
            return False
        if (
            type(session_epoch) not in (int, float)
            or not math.isfinite(session_epoch)
            or session_epoch < 0
            or type(input_revision) is not int
            or input_revision < 0
            or (
                provider_generation is not None
                and (type(provider_generation) is not int or provider_generation < 0)
            )
        ):
            return False
        try:
            if not current():
                return False
            research = None
            if self.research_enabled and provider_generation is not None:
                from .podview_research import extract

                research = extract(tool_name, result, now=time.time())
            projected = _facts(tool_name, result) if research is None else None
            if projected is None and research is None:
                return False
            if research is not None:
                summary, provenance = research["summary"], research["provenance"]
                if research["family"] == "answer-timeline":
                    # Same bounded selector fact anatomy; preserve mapping to source
                    # periods. Six candidates fit existing model/request bounds.
                    research["events"] = research["events"][:6]
                    facts = [
                        {
                            "id": e["id"],
                            "label": e["time"],
                            "value": e["label"],
                            "detail": e["detail"],
                        }
                        for e in research["events"]
                    ]
                else:
                    facts = research["facts"]
            else:
                assert projected is not None
                summary, facts, _suggested, provenance = projected
            if not all(_text(f["value"], 80) and _text(f["detail"], 200) for f in facts):
                return False
            if not current():
                return False
        except Exception:
            return False  # Optional presentation cannot break the conversation owner.
        key = (
            owner,
            session_id,
            session_epoch,
            turn_id,
            provider_generation,
            task_id,
            input_revision,
        )
        previous = self._rooms.get(room_id)
        if previous is None and len(self._rooms) >= 12:
            return False
        if previous is None or previous["key"] != key:
            state: dict = {
                "key": key,
                "current": current,
                "seen": set(),
                "items": [],
                "revision": (previous["revision"] if previous else 0) + 1,
            }
            self._rooms[room_id] = state
        else:
            state = previous
        if call_id in state["seen"] or len(state["seen"]) >= 32:
            return False
        state["seen"].add(call_id)
        receipt_id = secrets.token_hex(16)
        source_id = "source:" + receipt_id
        content = {
            "summary": summary,
            "facts": [
                {"id": f"fact:{number}", **fact, "sourceId": source_id}
                for number, fact in enumerate(facts)
            ],
            "sources": [
                {
                    "id": source_id,
                    "kind": "owner_receipt",
                    "receiptId": receipt_id,
                    "label": "HA-værktøjets resultat",
                    "scope": "tool_result",
                }
            ],
        }
        item = {
            "receiptId": receipt_id,
            "sessionId": session_id,
            "turnId": turn_id,
            "taskId": task_id,
            "inputRevision": input_revision,
            "observedAt": time.time(),
            "family": "fact-card",
            "displaySuggested": False,
            "provenance": provenance,
            "content": content,
        }
        row = {"item": item, "deadline": self._clock() + 120, "tool": tool_name}
        if research is not None:
            item.update(
                schema="podview.research.v1",
                roomId=room_id,
                sessionEpoch=session_epoch,
                providerGeneration=provider_generation,
                answerRevision=state["revision"],
                validUntil=research["validUntil"],
                allowedActions=[],
            )
            provenance["validUntil"] = research["validUntil"]
            if research["family"] == "fact-card":
                # Timestamp shared with extractor; don't turn a later publish into
                # a fresh source observation.
                item["observedAt"] = provenance["retrievedAt"]
                row["sourceText"] = research["sourceText"]
            else:
                item["family"] = "answer-timeline"
                row["selection_content"] = copy.deepcopy(content)
                events = [{**event, "sourceId": source_id} for event in research["events"]]
                item["content"] = {
                    "summary": summary,
                    "events": events,
                    "sources": content["sources"],
                }
                provenance.update(
                    displayedPeriods=len(events),
                    displayedStart=events[0]["time"],
                    displayedEnd=events[-1]["time"],
                )
        state["items"].insert(0, row)
        del state["items"][3:]
        state["revision"] += 1
        if self._selector is not None and not state.get("selection_offered"):
            state["selection_offered"] = True
            if self._selection is None or self._selection.done():
                try:
                    loop = asyncio.get_running_loop()
                except RuntimeError:
                    return True
                self._selection = loop.create_task(self._select(room_id, state, row))
        return True

    def _current(self, room_id: str, owner: object | None = None) -> dict | None:
        state = self._rooms.get(room_id)
        if self._closed or state is None:
            return None
        try:
            valid = (owner is None or state["key"][0] is owner) and state["current"]()
        except Exception:
            valid = False
        before = len(state["items"])
        state["items"] = [
            r
            for r in state["items"]
            if valid
            and self._clock() < r["deadline"]
            and time.time() < r["item"]["provenance"].get("validUntil", float("inf"))
        ]
        if before != len(state["items"]):
            state["revision"] += 1
        return state

    def snapshot(self, room_id: str, owner: object | None = None) -> dict:
        state = self._current(room_id, owner)
        items = (
            copy.deepcopy(
                [r["item"] for r in state["items"] if r["item"]["displaySuggested"] is True]
            )
            if state
            else []
        )
        for item in items:
            assert state is not None
            if item.get("schema") == "podview.research.v1":
                item["answerRevision"] = state["revision"]
        return {
            "schema": "podview.answers.v1",
            "roomId": room_id,
            "revision": state["revision"] if state else 0,
            "items": items,
        }

    def source(self, room_id: str, receipt_id: str, owner: object | None = None) -> dict | None:
        state = self._current(room_id, owner)
        row = (
            next((r for r in state["items"] if r["item"]["receiptId"] == receipt_id), None)
            if state
            else None
        )
        if state is None or row is None or row["item"]["displaySuggested"] is not True:
            return None
        item = row["item"]
        if item.get("schema") == "podview.research.v1":
            result = copy.deepcopy(item)
            result["answerRevision"] = state["revision"]
            result.update(
                schema="podview.research.source.v1",
                kind="owner_receipt",
                toolName=row["tool"],
                externalSourcesProvided=False,
            )
            if "sourceText" in row:
                result["sourceText"] = row["sourceText"]
            return result
        return {
            "schema": "podview.source.v1",
            "kind": "owner_receipt",
            "receiptId": receipt_id,
            "toolName": row["tool"],
            "observedAt": item["observedAt"],
            "summary": item["content"]["summary"],
            "facts": copy.deepcopy(item["content"]["facts"]),
            "externalSourcesProvided": False,
            "provenance": copy.deepcopy(item["provenance"]),
        }

    def close(self) -> None:
        self._closed = True
        if self._selection is not None:
            self._selection.cancel()
        self._rooms.clear()

    async def aclose(self) -> None:
        self.close()
        if self._selection is not None:
            await asyncio.gather(self._selection, return_exceptions=True)

